/* ── What the caller may do to this document, as the server will decide it ──
   2026-09-28, coverage-gap sweep GE-P-3. Freeze, E-sign, Assign review and
   File to vault were offered to every member who could open a document; a
   member without the grant filled in the governed dialog (a freeze reason, a
   password) and only then met the refusal. This reports, per act, the SAME
   decision the write will meet, computed by the same code — never a second
   permission model:

     freeze        authoringObjectAuthorization classifies /freeze as
                   'approve' → decideAuthoringPermission (OWNER or APPROVER
                   grant, or a global admin role), then — a freeze is signed
                   (DP-35) — the same §11.10(g) check as esign.
     esign         the same 'approve' decision, then the §11.10(g) check
                   (checkSigningAuthority, as the e-sign route asks it).
     esignReview   the review signature alone (meaning REVIEWER), which the
                   middleware classes as 'review' (REVIEWER, APPROVER or OWNER
                   grant), then the same §11.10(g) check (QA 2026-10-08, j4).
     fileToVault   authoringObjectAuthorization classifies /file-to-vault as
                   'export' (any status; OWNER, AUTHOR or APPROVER), then the
                   vault ingest's vaultWriteRefusal() on the request's
                   tenant-scope role.
     assignReview  Send for review. POST /api/tasks/tasks runs
                   requireEditorAccess, whose role rule is membership of
                   GOVERNED_WRITE_ROLES on the request's role — the same set,
                   read the same way, here. Then POST
                   /documents/:id/request-review, which
                   authoringObjectAuthorization classifies as 'edit' (wave 2D):
                   an OWNER or AUTHOR grant, or a global admin, on a document
                   that is not sealed.

   Each entry is `{ allowed, reason }`, or null when this read could not
   determine it (a lookup failed, no tenant scope): the client treats null as
   unknown and leaves the control to the server. The write routes still
   enforce; this only tells the user before they start. */
type DocumentActGate = { allowed: boolean; reason: string | null } | null;

function titleCaseRoles(roles: readonly string[] | undefined): string {
  const names = (roles ?? []).map(r => r.charAt(0) + r.slice(1).toLowerCase());
  return names.length ? names.join(', ') : 'none';
}

function objectGate(
  decision: AuthoringPermissionDecision,
  act: string,
  needs: string,
): DocumentActGate {
  if (decision.allowed) return { allowed: true, reason: null };
  if (decision.reason === 'document-immutable') {
    return {
      allowed: false,
      reason: `${act} is refused while the document's status is ${decision.scope?.documentStatus ?? 'unknown'}.`,
    };
  }
  if (decision.reason === 'organization-read-only') {
    return { allowed: false, reason: `${act} needs an editing role in this organization. Your current organization access is read-only.` };
  }
  if (decision.reason === 'permission-denied') {
    return {
      allowed: false,
      reason: `${act} needs ${needs} on this document. Your grants on it: ${titleCaseRoles(decision.matchedRoles)}.`,
    };
  }
  return null; // principal-missing / object-not-found: not a decision about this user
}

/** A refusal is certain when either step refuses; otherwise unknown if either is unknown. */
function bothGates(first: DocumentActGate, second: DocumentActGate): DocumentActGate {
  if (first && !first.allowed) return first;
  if (second && !second.allowed) return second;
  if (!first || !second) return null;
  return { allowed: true, reason: null };
}

async function settle<T>(what: string, docId: string, fn: () => Promise<T> | T): Promise<T | null> {
  try {
    return await fn();
  } catch (error) {
    logger.warn('Document access could not be determined; reported as unknown', {
      what,
      docId,
      error: error instanceof Error ? error.message : String(error),
    });
    return null;
  }
}

/** QMS content and signature standing stay separate: a controlled editing copy
 * can refuse further text changes while its current governance status is read. */
async function qmsDocumentAccessGates(tenantId: number, docId: string): Promise<{ content: DocumentActGate; signing: DocumentActGate }> {
  const { qmsAuthoringWriteRefusal, qmsAuthoringGovernanceRefusal } = await import('../services/qms/controlled-document-content');
  const [content, governance] = await Promise.all([
    qmsAuthoringWriteRefusal(pool, tenantId, docId), qmsAuthoringGovernanceRefusal(pool, tenantId, docId),
  ]);
  return {
    content: content ? { allowed: false, reason: content.error } : { allowed: true, reason: null },
    signing: governance ? { allowed: false, reason: governance.error } : { allowed: true, reason: null },
  };
}

async function callerDocumentAccess(req: Request, tenantId: number, docId: string) {
  const unknown = { edit: null, freeze: null, esign: null, esignReview: null, fileToVault: null, assignReview: null, placeIntoFiling: null } as Record<
    'edit' | 'freeze' | 'esign' | 'esignReview' | 'fileToVault' | 'assignReview' | 'placeIntoFiling',
    DocumentActGate
  >;
  const principal = authoringPrincipalFromRequest(req);
  if (!principal) return unknown;
  const scope = await settle('scope', docId, () => resolveAuthoringDocumentScope(pool, tenantId, docId));
  if (!scope) return unknown;
  const qmsGates = await qmsDocumentAccessGates(tenantId, docId);
  const editGate = await settle('edit', docId, async () =>
    objectGate(await decideAuthoringPermission({ pool, principal, scope, action: 'edit' }), 'Editing', 'an Owner or Author grant'),
  );

  const approve = await settle('approve', docId, () =>
    decideAuthoringPermission({ pool, principal, scope, action: 'approve' }),
  );
  const produce = await settle('export', docId, () =>
    decideAuthoringPermission({ pool, principal, scope, action: 'export' }),
  );
  /* The review signature (POST /e-sign, meaning REVIEWER) is a 'review' act —
     authoringObjectAuthorization classes it so (QA 2026-10-08, j4). */
  const review = await settle('review', docId, () =>
    decideAuthoringPermission({ pool, principal, scope, action: 'review' }),
  );
  const approveGate = (act: string) =>
    approve ? objectGate(approve, act, 'an Owner or Approver grant') : null;

  /* resolveSignerOrgRole answers null for "no membership row" (the e-sign
     route refuses that) and throws when the lookup fails (unknown here). */
  const signing = await settle('signing-role', docId, async () => ({
    role: await resolveSignerOrgRole(Number(getActorId(req)), tenantId),
  }));
  const signingGate: DocumentActGate = !signing
    ? null
    : isSigningAuthorized(signing.role)
      ? { allowed: true, reason: null }
      : {
          allowed: false,
          reason:
            'Applying an electronic signature needs a signing role in this organization ' +
            `(${signingAuthorityRoles().join(', ')}). Your role: ${signing.role ?? 'none recorded'}.`,
        };

  /* An org role ABSENT from this request is not evidence the write request
     will lack one (it is attached upstream, by the global /api gate), so both
     role checks below report unknown rather than a refusal in that case. */
  const vaultGate = await settle('vault-role', docId, (): DocumentActGate => {
    const role = String(getTenantScope()?.role ?? '').toLowerCase();
    if (!role) return null;
    if (!vaultWriteRefusal()) return { allowed: true, reason: null };
    return {
      allowed: false,
      reason: `Filing into the vault needs an editing role in this organization. Your role: ${role}.`,
    };
  });

  /* Send for review meets two checks, reported in this order so a viewer reads
     the organization-role sentence first: the role (requireEditorAccess on the
     task create), then the document. POST /documents/:id/request-review is
     classified 'edit' by authoringObjectAuthorization since wave 2D: an Owner
     or Author grant, or a global admin, on a document that is not sealed. Until
     then this reported the role only, so a member without the grant, or anyone
     on a FROZEN document, was offered the control and refused after filling it
     in (docs/evidence/D2-ONE-ANA/2026-10-08/ana-2d-review-loop-closes/). */
  const assignGate = await settle('editor-access', docId, async (): Promise<DocumentActGate> => {
    const role = String((req as Request & { userRole?: string }).userRole || req.user?.role || '').toLowerCase();
    const roleGate: DocumentActGate = !role
      ? null
      : GOVERNED_WRITE_ROLES.has(role)
        ? { allowed: true, reason: null }
        : { allowed: false, reason: `Sending for review needs an editing role in this organization. Your role: ${role}.` };
    if (roleGate && !roleGate.allowed) return roleGate;
    const edit = await settle('edit', docId, () => decideAuthoringPermission({ pool, principal, scope, action: 'edit' }));
    return bothGates(roleGate, edit ? objectGate(edit, 'Sending for review', 'an Owner or Author grant') : null);
  });

  /* Place into filing (FILING_SPINE.md F17). Its two writes, the filing copy
     (POST /api/coauthor/documents with a source) and the leaf (PUT
     /api/submissions/sequences/:id/leaves), each run
     requireRole('regulatory-author') over req.user's expanded role claims.
     The org role is read as Send for review reads it, and expanded as it is
     where those writes run, then judged by requireRole's own decision
     (roleClaimsSatisfy). A viewer was offered the control and met a 403 after
     filling it in (design review 2026-10-08, Part 11 lens). */
  const placeRole = String((req as Request & { userRole?: string }).userRole || req.user?.role || '').toLowerCase();
  const placeGate: DocumentActGate = !placeRole
    ? null
    : roleClaimsSatisfy({ roles: expandRoleClaims(placeRole, undefined) }, ['regulatory-author'])
      ? { allowed: true, reason: null }
      : { allowed: false, reason: `Placing into a filing needs an authoring role in this organization. Your role: ${placeRole}.` };

  return {
    edit: bothGates(qmsGates.content, editGate),
    // A freeze is signed (DP-35): the same two decisions as E-sign.
    freeze: bothGates(qmsGates.signing, bothGates(approveGate('Freezing'), signingGate)),
    esign: bothGates(qmsGates.signing, bothGates(approveGate('Signing'), signingGate)),
    // The review signature alone: a Reviewer grant suffices for it.
    esignReview: bothGates(qmsGates.signing, bothGates(
      review ? objectGate(review, 'Signing the review', 'a Reviewer, Approver or Owner grant') : null,
      signingGate,
    )),
    fileToVault: bothGates(
      produce ? objectGate(produce, 'Filing to the vault', 'an Owner, Author or Approver grant') : null,
      vaultGate ?? null,
    ),
    assignReview: bothGates(qmsGates.content, assignGate ?? null),
    placeIntoFiling: placeGate,
  };
}

// GET /api/authoring/docs/:docId - Get document details
router.get('/docs/:docId', async (req: Request, res: Response) => {
  try {
    const { docId } = req.params;
    const tenantId = getTenantId(req);

    const docResult = await pool.query(
      `SELECT
        d.id, d.title, d.module, d.product_code, d.locale, d.status, d.created_at, d.updated_at, d.created_by, d.template_id, d.submitted_at, d.current_workflow_id, d.approved_at, d.frozen_at, d.locked_at, d.locked_by, d.tenant_id, d.version,
        to_jsonb(d)->>'c2c_document_id' AS c2c_document_id,
        COUNT(DISTINCT s.id) as section_count,
        COUNT(DISTINCT c.id) as comment_count,
        COUNT(DISTINCT r.id) as revision_count
       FROM authoring_documents d
       -- Same defect, same fix as the per-section counters below: only the
       -- document was tenant-scoped, so its own section / comment / revision
       -- counts included rows belonging to other tenants.
       LEFT JOIN authoring_sections s ON s.doc_id     = d.id AND s.tenant_id = d.tenant_id
       LEFT JOIN authoring_comments c ON c.doc_id     = d.id AND c.tenant_id = d.tenant_id
       LEFT JOIN doc_revisions r      ON r.section_id = s.id AND r.tenant_id = s.tenant_id
       WHERE d.id = $1 AND d.tenant_id = $2
       GROUP BY d.id`,
      [docId, tenantId]
    );

    if (((docResult.rowCount ?? 0) === 0)) {
      return res.status(404).json({
        success: false,
        error: 'Document not found',
      });
    }

    /* Provenance (WM, 2026-09-21): whether AnA drafted this document, a seed
       produced it or it was imported — NULL when a person authored it. Read
       through the service so a deployment without the 20260921 column reports
       `provenanceStore` honestly instead of a null that reads as "a person". */
    const prov = await readDocumentProvenance(pool, String(docId), tenantId);
    /* GE-P-3 (2026-09-28): what this caller may do here — see callerDocumentAccess. */
    const access = await callerDocumentAccess(req, tenantId, String(docId));
    res.json({
      success: true,
      document: { ...docResult.rows[0], provenance: prov.provenance },
      access,
      ...(prov.provenanceStore !== 'present' ? { provenanceStore: prov.provenanceStore } : {}),
    });
  } catch (error) {
    console.error('Error getting document:', error);
    return serverError(res, logger, 'loading docs', error);
  }
});

// GET /api/authoring/docs/:docId/sections - Get all sections for a document
router.get('/docs/:docId/sections', async (req: Request, res: Response) => {
  try {
    const { docId } = req.params;
    const tenantId = getTenantId(req);

    const result = await pool.query(
      `SELECT
        s.id, s.doc_id, s.code, s.title, s.content, s.order_index, s.track_changes, s.created_at, s.updated_at, s.tenant_id,
        COUNT(DISTINCT c.id) as comment_count,
        COUNT(DISTINCT r.id) as revision_count,
        COUNT(DISTINCT ct.id) as citation_count
       FROM authoring_sections s
       -- The counters must count what the panels list (MDX UAT item A5).
       -- Reported as an off-by-one: the toolbar read "History 2" / "2 revisions"
       -- while the history panel said "No prior revisions". It is not an
       -- off-by-one -- the two sides ran differently-scoped queries. Only the
       -- section carried a tenant predicate, so these joins counted every row in
       -- the three child tables that matched on id ALONE, across tenants, while
       -- every panel that LISTS them is tenant-scoped (history, comments and
       -- citations all filter their own tenant_id). Any row whose tenant_id did
       -- not match the section's -- another tenant's, or a null one -- was
       -- counted and then not shown.
       --
       -- Scoping the joins makes the label and the list the same question. It
       -- also closes a cross-tenant count leak: the old form disclosed the
       -- existence of other tenants' rows through a number on the toolbar.
       LEFT JOIN authoring_comments c  ON c.section_id  = s.id AND c.tenant_id  = s.tenant_id
       LEFT JOIN doc_revisions r       ON r.section_id  = s.id AND r.tenant_id  = s.tenant_id
       LEFT JOIN authoring_citations ct ON ct.section_id = s.id AND ct.tenant_id = s.tenant_id
       WHERE s.doc_id = $1 AND s.tenant_id = $2
       GROUP BY s.id
       ORDER BY s.order_index, s.created_at`,
      [docId, tenantId]
    );

    /* Two structural facts about the document as a whole, computed from the
       rows just read — no second query, and every client that already reads
       this endpoint gets them.

       They are worth stating because neither is visible from any one section:
       a code filed twice puts two 3.2.S in the assembled dossier with nothing
       to say which is meant, and a stored order that disagrees with the codes
       means the dossier assembles in the wrong order. Documents created before
       the section-create path assigned a real position have every section at
       index 0, so this is how one is recognised. */
    const structure = sectionStructureIssues(
      result.rows.map((r: { code?: string | null }) => String(r.code ?? '')),
    );

    res.json({
      success: true,
      sections: result.rows,
      count: result.rowCount,
      structure,
    });
  } catch (error) {
    console.error('Error getting sections:', error);
    return serverError(res, logger, 'loading sections', error);
  }
});

// POST /api/authoring/sections - Create new section
router.post('/sections', async (req: Request, res: Response) => {
  try {
    const tenantId = getTenantId(req);
    const createdBy = getActorId(req);
    if (!createdBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    // The create — the parent's immutability lock, the position the code
    // belongs at (FOR UPDATE), the INSERT + lineage gate in one transaction,
    // then the genesis revision and the CREATE audit row — is
    // services/authoring/authoring-documents.ts createSection.
    const outcome = await createSection(createContext(req, tenantId, createdBy), req.body ?? {});
    if (outcome.kind === 'refused') {
      // `code` (e.g. SECTION_CODE_EXISTS, a 409) is what a client branches on.
      return res
        .status(outcome.status)
        .json({
          success: false,
          error: outcome.error,
          ...(outcome.code ? { code: outcome.code } : {}),
          ...(outcome.code === 'SECTION_CODE_EXISTS' ? { field: 'code' } : {}),
        });
    }
    if (outcome.kind === 'lineage_failed') {
      return res.status(500).json({
        success: false,
        error: {
          code: 'LINEAGE_REQUIRED',
          message:
            'The section was not created: its data lineage could not be recorded. ' +
            'Saving content without provenance is not permitted.',
        },
      });
    }

    res.status(201).json({
      success: true,
      section: outcome.section,
      message: 'Section created successfully',
    });
  } catch (error) {
    console.error('Error creating section:', error);
    return serverError(res, logger, 'saving sections', error);
  }
});

// PATCH /api/authoring/sections/:sectionId - Update section (with automatic revision)
router.patch('/sections/:sectionId', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { content, track_changes, title, code } = req.body;
    /* WHICH WORDS a machine author wrote, as the client claims it. Read off
       the marks before accepting strips them; the server keeps only the ids it
       names itself, and each entry carries the AnA turn record the words came
       from so the claim can be CHECKED (round 15, SEC-A-7 door 1). Nothing is
       believed here — `creditMachineClaims` below decides, once, for both
       channels. */
    const acceptedMachine = acceptedMachineText(req.body?.acceptedMachineText);
    /* And WHO the save says contributed. No longer a second, unchecked claim:
       it is disclosed on the Part 11 row, and the contributors the revision
       and the filing actually record are derived from the verdict on the words
       (`contributorsOf`). Before round 15 this list alone set the revision's
       origin to `ai-draft-accept`, wrote the machine into `inputs.contributors`
       and became the filing's `draft_source` — with no words to check against
       any record. `settleAcceptedContributions` in the editor sends no author
       without its text, so the two channels agree for every current client. */
    const claimedAuthors = machineContributors(req.body?.acceptedAuthors);
    const tenantId = getTenantId(req);
    const updatedByUser = getActorId(req);
    if (!updatedByUser) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    // Get current section data for revision
    const currentSection = await pool.query(
      'SELECT id, doc_id, code, title, content, order_index, track_changes, created_at, updated_at, tenant_id FROM authoring_sections WHERE id = $1 AND tenant_id = $2',
      [sectionId, tenantId]
    );

    if (((currentSection.rowCount ?? 0) === 0)) {
      return res.status(404).json({
        success: false,
        error: 'Section not found',
      });
    }

    /* LAST WRITE NO LONGER SILENTLY WINS.
     *
     * This UPDATE was `WHERE id = $n AND tenant_id = $n` and nothing else, and
     * the client sent only `{ content }`. So two authors on one section — the
     * normal case for a CTD module, where a writer and a reviewer work the same
     * §3.2.P.5 at once — ended with whoever saved second replacing the OTHER'S
     * ENTIRE SECTION. No 409, no warning, no merge, no "this changed while you
     * were editing". The overwrite then entered the hash-chained revision
     * ledger as an ordinary authored revision, so the record does not show a
     * collision either; the only way back is for someone to notice and revert.
     *
     * `updated_at` is the concurrency token because it is already on the row
     * the client loaded, already returned by every read, and already bumped by
     * every write — no new column, no new migration, nothing to keep in sync.
     *
     * OPT-IN, deliberately. A client that sends no `expectedUpdatedAt` keeps
     * the old behaviour rather than being refused: a caller that PATCHes a
     * section without having read a timestamp cannot hit the race, and failing
     * it closed would break saving to fix nothing. The editor sends it;
     * anything that does not is exactly as safe as it was yesterday and no
     * less.
     *
     * This comment used to name "the MDX dossier drawer" as one of those
     * callers. It is not a caller of this route at all: it PATCHes
     * `/api/c2c/documents/:id/sections/:key` (mdx/hooks/useSectionSave.ts),
     * the FILING side. Correcting it is not housekeeping — the stale line said
     * the drawer saved through this door, which is seal-guarded, and so helped
     * hide that the door it really uses was not (round 15, the exit-path
     * verification). The other two client PATCHes here carry `track_changes`
     * or `code`/`title` only. */
    const expectedUpdatedAt = req.body?.expectedUpdatedAt;
    if (typeof expectedUpdatedAt === 'string' && expectedUpdatedAt.trim()) {
      const current = currentSection.rows[0]?.updated_at;
      const currentMs = current ? new Date(current).getTime() : NaN;
      const expectedMs = new Date(expectedUpdatedAt).getTime();
      if (Number.isFinite(currentMs) && Number.isFinite(expectedMs) && currentMs !== expectedMs) {
        return res.status(409).json({
          success: false,
          error: {
            code: 'SECTION_CHANGED',
            message:
              'This section was changed by someone else while you were editing. ' +
              'Your text has not been saved and nothing was overwritten — reload the ' +
              'section to see their version, then reapply your changes.',
          },
          /* The caller can show WHEN it moved under them without another read. */
          currentUpdatedAt: current,
        });
      }
    }

    /* ── A SECTION'S CODE IS ITS IDENTITY IN THE FILING ──
     *
     * `commitSectionToFiling` matches `authoring_sections.code` to
     * `c2c_document_sections.section_key`. So changing the code on a BOUND
     * document does not rename anything — it silently re-points the section to
     * a DIFFERENT filing slot (or to none), and the next content save lands
     * there instead, orphaning the old slot's content. Nothing warned; the
     * rename dialog offered the code as a freely editable field.
     *
     * Refused, fail-closed. The title renames freely — that is a label. The
     * code is structure, and re-keying a bound section is not a rename. If a
     * "move this section to another filing slot" operation is ever wanted, it
     * is a deliberate feature with its own rules (is the target occupied? is it
     * in the rule pack?), not a side effect of the rename field. An UNBOUND
     * document has no filing linkage to break, so its codes stay editable. */
    if (code !== undefined && String(code) !== String(currentSection.rows[0].code ?? '')) {
      /* This predicate names c2c_document_id, which a deployment carrying the
         authoring bundle without the c2c one does not have — the same shape the
         create path above already copes with, and which
         commit-section-to-filing.ts treats as a supported deployment rather
         than an error. Unguarded, the catalog raises 42703 and a section
         rename answers 500 on those deployments.

         Each state has a different correct answer, so they are not collapsed:
           present — ask, and lock the code if the document is bound.
           absent  — no document here CAN be bound, so there is no filing
                     linkage to break and the code stays editable, exactly as
                     the comment above says of an unbound document.
           unknown — the check did not run, so whether this document is bound
                     is not known. Refuse. The lock exists to stop a rename
                     silently re-pointing a section to a different filing slot
                     and orphaning the old slot's content; allowing it on an
                     unverified guess risks that, while refusing costs a retry. */
      const columnState = await bindingColumnState();
      if (columnState === 'unknown') {
        return res.status(503).json({
          success: false,
          error: {
            code: 'BINDING_CHECK_UNAVAILABLE',
            message:
              'Whether this section is bound to a filing slot could not be checked, so its code ' +
              'was not changed. Nothing was modified. Try again.',
          },
        });
      }
      const bound =
        columnState === 'present'
          ? await pool.query(
              `SELECT 1 FROM authoring_documents
                WHERE id = $1 AND tenant_id = $2 AND c2c_document_id IS NOT NULL`,
              [currentSection.rows[0].doc_id, tenantId],
            )
          : { rowCount: 0 };
      if ((bound.rowCount ?? 0) > 0) {
        return res.status(409).json({
          success: false,
          error: {
            code: 'CODE_LOCKED_TO_FILING',
            message:
              'This section’s code is its place in the filing, so it cannot be changed here. ' +
              'Re-coding it would break the link between this section and the filing slot it fills, ' +
              'and its content would stop reaching the filing. The title can be renamed freely.',
          },
        });
      }
    }

    // Build update query dynamically
    const updates = [];
    const values = [];
    let paramCount = 0;
    let recordRevision = false;

    if (content !== undefined) {
      /* AN IMAGE IN A SECTION IS AN UPLOADED FIGURE OR NOTHING (periodic review
         2026-09-28, editor family, SEC-B-1, SEC-B-2). This save stored any
         `<img src>` it was sent, so one editor could plant a request that every
         later reader's browser made in the reader's own name (dot segments walk
         `/api/authoring/images/` out to any API route), or an image on another
         site that every reader's browser fetched. Refused with the images named,
         before anything is written, and never rewritten: a governed record's
         content changes only when its author changes it. */
      const { refusedFigures, describeRefusedFigures } = await import(
        '../services/authoring/authoring-html-sanitizer'
      );
      const refused = await refusedFigures(typeof content === 'string' ? content : String(content ?? ''));
      if (refused.length > 0) {
        return res.status(400).json({
          success: false,
          error: { code: 'FIGURE_NOT_UPLOADED', message: describeRefusedFigures(refused) },
          field: 'content',
          refusedImages: refused.map(({ position, src }) => ({
            position,
            src: src.length > 200 ? `${src.slice(0, 200)}…` : src,
          })),
        });
      }
      paramCount++;
      // `$$` is the placeholder's `$` followed by the interpolation. fde9d704 lost
      // it, so the SQL read `content = 1` with the bound value unused, Postgres
      // refused the UPDATE, and every section content save answered 500.
      updates.push(`content = $${paramCount}`);
      values.push(content);
      recordRevision = true;
    }

    // §11.10(e): a content change carries its reason, checked here rather
    // than trusted from the client, and refused before anything is written.
    let changeReason: string | null = null;
    if (recordRevision) {
      const verdict = requireGovernedReason(req.body?.changeReason);
      if (!verdict.ok) return res.status(400).json({ error: verdict.error, field: 'changeReason' });
      changeReason = verdict.reason;
    }

    if (title !== undefined) {
      paramCount++;
      updates.push(`title = $${paramCount}`);
      values.push(title);
    }

    if (code !== undefined) {
      paramCount++;
      updates.push(`code = $${paramCount}`);
      values.push(code);
    }

    if (track_changes !== undefined) {
      paramCount++;
      updates.push(`track_changes = $${paramCount}`);
      values.push(track_changes);
    }

    // Always update the updated_at timestamp
    updates.push('updated_at = NOW()');

    // Add section_id and tenant_id to values
    values.push(sectionId, tenantId);

    const updateQuery = `
      UPDATE authoring_sections
      SET ${updates.join(', ')}
      WHERE id = $${paramCount + 1} AND tenant_id = $${paramCount + 2}
      RETURNING *
    `;

    // ── One atomic save ───────────────────────────────────────────────────────
    // Revision + section update + lineage + filing commit + audit are ONE atomic
    // unit on ONE connection. Previously the revision and audit writes ran as
    // their own pool commits while the lineage/filing gate ran in a separate
    // transaction, so a failure between them left the trail out of step with the
    // section — or, worse, produced saved text with no provenance and no signal
    // it had happened. A single BEGIN/COMMIT makes all of it land together or not
    // at all; any error rolls the whole thing back and the caller is told. A
    // refused save is recoverable; a document that quietly lost its provenance,
    // its filing commit, or its audit record is not.
    /* ── THE GOVERNED-WRITE VERDICT, BEFORE THE TRANSACTION OPENS ───────────
     * One verdict on every machine-text claim this save carries: the record
     * must hold the words, and CLAUDE.md RULE 2 must admit every model that
     * served the turn. Only a credited claim is attributed to the machine;
     * everything else is saved as this person's own assertion, with the claim
     * and its reason on the Part 11 row and on the response.
     *
     * Here rather than inside the transaction because the rows it reads are
     * append-only — so nothing it sees can change under the write — and
     * because a failed statement inside the BEGIN would abort the very write
     * it is checking. Only on a content save: a rename carries no words.
     *
     * An unverifiable claim does not refuse the save; a VERIFIED one whose
     * model RULE 2 does not admit does. governed-machine-claims.ts states why
     * the two cases differ. */
    const machineClaims: GovernedClaimVerdict =
      content !== undefined
        ? await creditMachineClaims(pool, tenantId, acceptedMachine)
        : { credited: [], refused: [], recordOccurrences: () => 0 };

    /* ── A VERIFIED CLAIM RULE 2 WILL NOT ADMIT STOPS THE SAVE ──────────────
     * Not the attribution — the save. The server has checked that the record
     * verifies whole, that the words are inside what AnA produced, and that a
     * serving model is one the rule does not admit for regulatory drafting.
     * Saving it anyway would write a named person as the author of words a
     * model demonstrably wrote, into a §11.10(e) lineage span and into the
     * filing itself. Refused before anything is written, and before the
     * transaction even opens.
     *
     * An UNVERIFIABLE claim is not refused — see governed-machine-claims.ts
     * for why the two cases differ, and why this refusal is only honest
     * because the editor keeps the claim for the retry. */
    const notAdmitted = refusedForModel(machineClaims);
    if (notAdmitted) {
      const refusal = governedSaveRefusal(notAdmitted);
      logger.warn('Section save refused: a verified machine claim names a model RULE 2 does not admit', {
        sectionId, tenantId, servedBy: refusal.servedBy, passages: refusal.passages,
      });
      return res.status(403).json({
        success: false,
        error: { code: refusal.code, message: refusal.message },
        servedBy: refusal.servedBy,
        turnRecordIds: refusal.turnRecordIds,
      });
    }

    /* What the Part 11 row and the saver are each told about the claims.
       Computed once: both are pure functions of the verdict, and calling them
       inside the object literal that uses them read as two decisions. */
    const claimDisclosure = machineClaimDisclosure(machineClaims, claimedAuthors);
    const claimReport = machineClaimReport(machineClaims);

    const client = await pool.connect();
    let result: { rows: any[] };
    // Whether the text reached the filing, and when it did not, why. Reported
    // on the response rather than dropped: an unbound save is legitimate, a
    // silently unbound one is how the two stores drifted apart.
    let governedCommit: CommitSectionResult | null = null;
    try {
      await client.query('BEGIN');
      await reserveWritableSection(client, String(sectionId), tenantId);

      // The previous body is a transaction-held fact, read after the parent
      // reservation and before this update. Client-supplied text and the
      // pre-reservation lookup cannot establish a retained span's integrity.
      const previous = content === undefined ? null : await client.query<{ content: string | null }>(
        'SELECT content FROM authoring_sections WHERE id=$1 AND tenant_id=$2 FOR UPDATE',
        [String(sectionId), tenantId],
      );

      result = await client.query(updateQuery, values);

      // The lineage gate: record an author span per clause and assert coverage,
      // in this transaction, so content and provenance commit together. Empty /
      // undefined content (a metadata-only update) is a no-op inside the helper.
      // req.params is typed `string | string[]`; document_id is the join key
      // every later read depends on, so coerce rather than let an array
      // stringify itself into one.
      const lineage = await enforceAuthorLineage(
        client,
        tenantId,
        { documentTable: 'authoring_sections', documentId: String(sectionId) },
        content,
        updatedByUser,
        {
          previousContent: previous ? previous.rows[0]?.content ?? '' : undefined,
          /* Only the claims a record vouched for. An unverifiable claim's
             clause is not dropped — no accepted-machine text matches it, so
             the gate records it as this person's own assertion, which is what
             they did by saving it. */
          acceptedMachineText: machineClaims.credited.map(({ authorId, text }) => ({ authorId, text })),
          /* And no clause is credited more times than the crediting records
             hold it (the batch-draft accept's rule, round 4, DUP). */
          recordOccurrences: machineClaims.recordOccurrences,
        },
      );

      /* ── WHO THE RECORD NAMES: WHAT THE GATE CREDITED, NOT WHAT WAS CLAIMED ──
       * `clausesInAcceptedText` is the gate's own count, and its contract is
       * explicit: "A caller that says a save accepted a machine's text says it
       * only when this is above zero". A verified claim of ONE WORD credits no
       * clause, and naming AnA on it would make the revision say
       * `ai-draft-accept`, the filing record `draft_source = 'ana'` and the
       * snapshot trigger record `author_kind = 'ana'` for a save in which the
       * lineage credited the machine with nothing — the defect the sibling
       * batch-draft door was corrected for in round 3, at the door that files
       * into c2c_documents.
       *
       * This is why the lineage gate now runs BEFORE the revision here, as it
       * already did at the revert (:2494) and at template-apply (:6142): what
       * a save says about itself has to follow what it credited. The gate
       * reads and writes span rows only, never the section row, so the order
       * is free. One machine author exists in the vocabulary today
       * (MACHINE_AUTHOR_IDS), so one count answers for it; a second id would
       * need the count per author. */
      const contributors = lineage.clausesInAcceptedText > 0 ? contributorsOf(machineClaims) : [];

      // A revision row means "this content, by this author, as of this time".
      // POST /sections already recorded (new content, author); this makes the
      // edit path agree with it. The prior content is not lost — it is the
      // preceding row. Only when content changed.
      if (recordRevision) {
        /* A save that incorporates accepted machine-authored text is not a
           plain human edit, and saying so is the whole point: the origin marks
           it in the chain hash, the contributor list names who drafted it. */
        await createRevision(
          sectionId,
          content,
          updatedByUser,
          tenantId,
          client,
          contributors.length ? 'ai-draft-accept' : 'human-edit',
          contributors,
        );
      }

      // ── Commit the working copy into the filing ─────────────────────────────
      // c2c_documents is the system of record; this store is the editing layer
      // over it. In THIS transaction on purpose: the filing and the working copy
      // move together or neither does, exactly like the lineage gate above.
      // Only when content changed, and only when the document is bound.
      if (content !== undefined) {
        governedCommit = await commitSectionToFiling({
          client,
          sectionId: String(sectionId),
          content: String(content ?? ''),
          actorId: String(updatedByUser),
          tenantId,
          reason: typeof req.body?.changeReason === 'string' ? req.body.changeReason : undefined,
          // Same signal createRevision's `origin` already uses two blocks up.
          // Only the machine-author id is ever written here — never a guessed
          // 'human' for the zero-contributor case, see commit-section-to-filing.ts.
          draftSource: contributors.length > 0 ? contributors[0].id : null,
        });
      }

      // Part 11 change record: operation, actor, before/after content, a SHA-256
      // of each side, reason, IP, user agent, session. Written on the same
      // transaction client so the audit row commits atomically with the edit it
      // records. In production createAuditTrail throws on failure, which rolls
      // the whole edit back rather than committing an un-audited change.
      if (recordRevision) {
        await createAuditTrail(
          req,
          result.rows[0]?.doc_id,
          sectionId,
          'UPDATE',
          currentSection.rows[0].content ?? null,
          content ?? null,
          changeReason,
          {
            titleChanged: title !== undefined,
            /* §11.10(a)/(e): a claim that AnA wrote some of this text is part
               of what changed, and until round 15 this row said nothing about
               one having been made. Credited claims name their turn record;
               refused ones carry the reason and, for a refused model, the
               models the record named. Absent when the save claimed nothing. */
            ...(claimDisclosure ? { machineText: claimDisclosure } : {}),
          },
          client,
        );
      } else {
        /* A METADATA CHANGE IS STILL A CHANGE TO A GOVERNED RECORD.
         *
         * The audit block above fired only on a content change, so a save that
         * renamed a section, re-coded it, or toggled its track-changes mode
         * updated the row and left NO audit trail at all. Renaming a CTD code
         * is not cosmetic — `commitSectionToFiling` matches a section to its
         * filing slot BY that code — and §11.10(e) wants every change to a
         * governed record recorded with who, when, and what moved.
         *
         * No revision (the revision ledger is for content, and none changed)
         * and no reason prompt (the action names itself, exactly like the
         * revert): the row records the field and its before/after, which is a
         * complete answer to "what changed". It rides the same transaction, so
         * a metadata change and its audit row commit together or neither does —
         * and because it goes through createAuditTrail on the caller's client,
         * it lands in the hash-chained ledger too, not only the soft table. */
        const cur = currentSection.rows[0] ?? {};
        const metaChanges: Array<{ field: string; from: unknown; to: unknown }> = [];
        if (title !== undefined && String(title) !== String(cur.title ?? '')) {
          metaChanges.push({ field: 'title', from: cur.title ?? null, to: title });
        }
        if (code !== undefined && String(code) !== String(cur.code ?? '')) {
          metaChanges.push({ field: 'code', from: cur.code ?? null, to: code });
        }
        if (
          track_changes !== undefined &&
          Boolean(track_changes) !== Boolean(cur.track_changes)
        ) {
          metaChanges.push({
            field: 'track_changes',
            from: Boolean(cur.track_changes),
            to: Boolean(track_changes),
          });
        }
        if (metaChanges.length) {
          const renamed = metaChanges.some((c) => c.field === 'title' || c.field === 'code');
          await createAuditTrail(
            req,
            result.rows[0]?.doc_id,
            sectionId,
            renamed ? 'RENAME' : 'TRACK_CHANGES',
            null,
            null,
            null,
            { source: 'section-metadata', changes: metaChanges },
            client,
          );
        }
      }

      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK').catch(() => {});
      if (workflowGovernanceReply(err, res)) return;
      if (err instanceof UnverifiedMachineFormattingError) {
        return res.status(err.status).json({ success: false,
          error: { code: err.code, message: err.message }, field: 'content' });
      }
      logger.error('Section save refused — content and lineage rolled back together', {
        sectionId,
        tenantId,
        err: err instanceof Error ? err.message : String(err),
      });
      return res.status(500).json({
        success: false,
        error: {
          code: 'LINEAGE_REQUIRED',
          message:
            'The section was not saved: its data lineage could not be recorded. ' +
            'Saving content without provenance is not permitted.',
        },
      });
    } finally {
      client.release();
    }

    res.json({
      success: true,
      section: result.rows[0],
      message: 'Section updated successfully',
      revision_created: content !== undefined,
      // Whether the text reached the filing. Present on every content save:
      // an unbound save is legitimate, a silently unbound one is the drift.
      ...(governedCommit ? { filing: filingResponse(governedCommit) } : {}),
      /* And what became of each machine-authorship claim. The saver has to be
         told: without it they see an ordinary "Section saved" while the record
         now says they asserted words they believed were attributed to AnA. */
      ...(claimReport ? { machineText: claimReport } : {}),
    });
  } catch (error) {
    if (workflowGovernanceReply(error, res)) return;
    console.error('Error updating section:', error);
    return serverError(res, logger, 'updating sections', error);
  }
});

// ============= History & Revisions =============

// GET /api/authoring/sections/:sectionId/history - Get revision history
router.get('/sections/:sectionId/history', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { limit = 50 } = req.query;
    const tenantId = getTenantId(req);

    const result = await pool.query(
      `SELECT
        r.id, r.section_id, r.content, r.created_by, r.created_at, r.tenant_id,
        r.content_sha256, r.chain_sha256, r.origin,
        u.name as created_by_name,
        u.email as created_by_email
       FROM doc_revisions r
       -- users.id is a serial (shared/schema.ts, migrations/0000_sweet_joseph.sql)
       -- and doc_revisions.created_by is TEXT holding String(req.user.id). The
       -- previous join was u.id = r.created_by::uuid — integer = uuid, which
       -- Postgres rejects at PARSE time (42883), so this endpoint returned 500
       -- on every call regardless of how many revisions existed, and the client
       -- rendered that failure as "No prior revisions".
       --
       -- The name comes from public.actor_name, not users: since users took
       -- row-level security (D3, 2026-09-28) a join on users found no one who
       -- had left the organization (docs/evidence/D3/2026-09-29-actor-names/).
       -- The cast is guarded so a non-numeric created_by cannot raise 22P02;
       -- it simply names nobody and the LEFT JOIN yields a null name.
       LEFT JOIN LATERAL public.actor_name(
         CASE WHEN r.created_by ~ '^[0-9]{1,9}$' THEN r.created_by::int END
       ) u ON TRUE
       WHERE r.section_id = $1 AND r.tenant_id = $2
       ORDER BY r.created_at DESC
       LIMIT $3`,
      [sectionId, tenantId, limit]
    );

    res.json({
      success: true,
      revisions: result.rows,
      count: result.rowCount,
    });
  } catch (error) {
    console.error('Error getting revision history:', error);
    return serverError(res, logger, 'loading history', error);
  }
});

// GET /api/authoring/sections/:sectionId/history/verify — recompute the
// revision ledger. Every verdict is recomputed from stored content; the hash
// columns are treated as claims to check, never as answers. An intact chain
// means: no revision's content was altered after it was written, no link was
// re-pointed, and nothing was appended unchained since the ledger was adopted.
// Rows predating the ledger are reported as pre-ledger, honestly, rather than
// backfilled into an integrity history nobody recorded at the time.
router.get('/sections/:sectionId/history/verify', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const tenantId = getTenantId(req);
    const { rows } = await pool.query(
      `SELECT id, content, created_by, origin, content_sha256, prev_chain_sha256, chain_sha256
         FROM doc_revisions
        WHERE section_id = $1 AND tenant_id = $2
        ORDER BY created_at ASC, id ASC`,
      [sectionId, tenantId]
    );
    const verdict = verifyLedger(rows);
    res.json({ success: true, revisionCount: rows.length, ...verdict });
  } catch (error) {
    console.error('Error verifying revision ledger:', error);
    res.status(500).json({ success: false, error: 'Failed to verify the revision ledger' });
  }
});

// POST /api/authoring/sections/:sectionId/revert - Revert to specific revision
router.post('/sections/:sectionId/revert', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { rev_id } = req.body;
    const tenantId = getTenantId(req);
    const revertedBy = getActorId(req);
    if (!revertedBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    if (!rev_id) {
      return res.status(400).json({
        success: false,
        error: 'rev_id is required',
      });
    }

    /* Get the revision — INCLUDING what it records about its own provenance
       (round 15, SEC-A-7 door 3). `origin` and `inputs.contributors` are on the
       append-only doc_revisions row, written by createRevision from the save
       door's MACHINE_AUTHOR_IDS-validated list. This SELECT used to name
       neither, so the one provenance fact the restored version carries about
       itself was discarded at the moment it was restored, and the filing then
       recorded NULL — "origin not stated" — over model prose. */
    const revResult = await pool.query(
      `SELECT id, section_id, content, created_by, created_at, tenant_id, origin, inputs
         FROM doc_revisions WHERE id = $1 AND section_id = $2 AND tenant_id = $3`,
      [rev_id, sectionId, tenantId]
    );

    if (((revResult.rowCount ?? 0) === 0)) {
      return res.status(404).json({
        success: false,
        error: 'Revision not found',
      });
    }

    const revision = revResult.rows[0];
    const restored = restoredMachineAuthor(revision.inputs);

    const currentSection = await pool.query(
      'SELECT content FROM authoring_sections WHERE id = $1 AND tenant_id = $2',
      [sectionId, tenantId]
    );
    if (((currentSection.rowCount ?? 0) === 0)) {
      return res.status(404).json({ success: false, error: 'Section not found' });
    }

    /* Content, its lineage and its ledger entry commit together or not at all
       — the identical rule the interactive save and the AI accept follow.
       Revert was the one content writer left non-transactional AND outside
       the lineage gate, so a reverted section's provenance quietly went stale.
       The restorer IS asserting this content now: author lineage records
       exactly that, and the revision's `origin: 'revert'` records that it was
       a restoration rather than fresh authorship. The section-row lock the
       UPDATE takes also serializes the ledger chain extension. */
    const client = await pool.connect();
    let result: { rows: any[] };
    /* Whether the restored text reached the filing, and when it did not, why.
       Not `| null` like the save's: a revert ALWAYS commits (the save does so
       only when content changed), and the catch below rethrows, so reaching
       the response means both this and `result` were assigned. Stating that
       keeps the branch out of the response and the handler under the
       complexity ratchet. */
    let governedCommit: CommitSectionResult;
    try {
      await client.query('BEGIN');
      await reserveWritableSection(client, String(sectionId), tenantId);
      result = await client.query(
        `UPDATE authoring_sections
         SET content = $1, updated_at = NOW()
         WHERE id = $2 AND tenant_id = $3
         RETURNING *`,
        [revision.content, sectionId, tenantId]
      );
      await enforceAuthorLineage(
        client,
        tenantId,
        { documentTable: 'authoring_sections', documentId: String(sectionId) },
        revision.content ?? '',
        revertedBy,
      );
      // The revert is itself an authored state: this content, restored by this
      // actor, now. Written AFTER the update for the same reason as the edit
      // path, and it replaces a pre-update createRevision that stored the
      // content being replaced under the reverter's name — the same
      // misattribution the edit path had.
      /* With the restored contributors, so the attribution survives a revert
         OF this revert: without them it would be recorded once and lost on the
         next restoration, which is the same erasure one step later. */
      await createRevision(sectionId, revision.content, revertedBy, tenantId, client, 'revert', restored.contributors);

      /* AND THE FILING MOVES WITH IT.
       *
       * This call was missing, and its absence reopened on the revert path the
       * exact divergence `commitSectionToFiling` exists to close. Revert wrote
       * the restored text to `authoring_sections` — the working copy — and left
       * `c2c_document_sections`, which is what the filing IS, holding whatever
       * the last PATCH had put there.
       *
       * So an author who reverted a bad edit saw the good text in the editor,
       * the revision ledger recorded the restoration, the audit trail recorded
       * a REVERT, and the filed document still contained the bad text. Every
       * record agreed a revert had happened and the one artifact that matters
       * disagreed — and nothing surfaced the disagreement, because each store
       * was internally consistent.
       *
       * The reason is stated rather than defaulted, and that is not the
       * fabrication REASON_NOT_STATED guards against: on an ordinary save the
       * system does not know why a human changed the words, so it must not
       * invent one. Here it does know — this is a restoration of a named
       * revision, which is a complete and truthful answer to "why did this
       * change". A mechanism describing itself is not a person being
       * impersonated. */
      /* The verdict is KEPT and reported, as the save (:2392) and the
         AI-draft accept (:4328) report theirs. It was discarded here, so a
         revert whose filing commit was refused answered a plain success while
         the filing kept the pre-revert text — each store internally
         consistent, nothing saying otherwise, which is the shape of the
         defect this very block's header describes one layer up. Found by the
         exit-path verification of round 15. */
      governedCommit = await commitSectionToFiling({
        client,
        sectionId: String(sectionId),
        content: String(revision.content ?? ''),
        actorId: String(revertedBy),
        tenantId,
        reason: `Reverted to revision ${rev_id}`,
        /* The restored revision's own machine author, so reverting TO
           AI-drafted text does not erase 'ana' from the system of record. An
           absent one still resolves to NULL — never a guessed 'human', which
           is what 20260822_section_version_author_kind_unspecified.sql closed
           one layer up. */
        draftSource: restored.draftSource,
      });

      /* 2026-09-28 (GE-P-1, coverage-gap sweep): the audit record for this
         revert is written HERE, on the transaction client, so it commits with
         the revert or not at all — as the save and freeze paths do. It ran
         after COMMIT on the pool: a failed audit write left a committed,
         unaudited revert, reported as a failure in production and as a
         success, with no audit row, elsewhere. On the caller's client the
         writer also records the hash-chained entry. */
      await createAuditTrail(
        req,
        result.rows[0]?.doc_id,
        sectionId,
        'REVERT',
        currentSection.rows[0]?.content ?? null,
        revision.content ?? null,
        `Reverted to revision ${rev_id}`,
        { revisionId: rev_id, revisionCreatedAt: revision.created_at },
        client,
      );

      await client.query('COMMIT');
    } catch (txErr) {
      await client.query('ROLLBACK').catch(() => {});
      throw txErr;
    } finally {
      client.release();
    }

    res.json({
      success: true,
      section: result.rows[0],
      message: `Section reverted to revision ${rev_id}`,
      reverted_from: revision.created_at,
      filing: filingResponse(governedCommit),
    });
  } catch (error) {
    console.error('Error reverting section:', error);
    return authoringWriterFailure(error, res, 'saving revert');
  }
});

// ============= Comments & Review =============

/**
 * What a comment's trail row records beside its words (after_content): the
 * passage it quotes with that passage's own hash, and the hash of the section
 * content the quote was taken from — so a quote can be matched to the
 * revision it read.
 */
function commentRecordMetadata(
  commentId: string,
  sectionId: string,
  parentCommentId: unknown,
  anchor: unknown,
  sectionContent: unknown,
): Record<string, unknown> {
  const quote =
    anchor && typeof anchor === 'object' && typeof (anchor as { quote?: unknown }).quote === 'string'
      ? (anchor as { quote: string }).quote
      : null;
  return {
    comment_id: commentId,
    section_id: sectionId,
    parent_comment_id: parentCommentId ?? null,
    anchor: anchor ?? null,
    quote,
    quoteSha256: quote ? textSha256(quote) : null,
    sectionContentSha256: textSha256(String(sectionContent ?? '')),
  };
}

/**
 * The comment and its record, on the caller's transaction. The section must be
 * this tenant's; the document is the SECTION's, and a body doc_id that names
 * another is refused; a reply belongs to a thread on the same section. Returns
 * the refusal rather than answering (nothing has been written by then), so the
 * caller responds once, after the transaction ends.
 */
async function writeAttributedComment(
  client: Queryable,
  req: Request,
  c: {
    commentId: string;
    sectionId: string;
    tenantId: number;
    body: string;
    anchor: unknown;
    claimedDocId: unknown;
    parentCommentId: unknown;
    positionData: unknown;
    createdBy: string;
    userName: string;
    userEmail: string | null;
  },
): Promise<{ ok: true; comment: Record<string, unknown> } | { ok: false; status: number; error: string }> {
  const section = await client.query(
    'SELECT id, doc_id, content FROM authoring_sections WHERE id = $1 AND tenant_id = $2',
    [c.sectionId, c.tenantId]
  );
  if ((section.rowCount ?? 0) === 0) return { ok: false, status: 404, error: 'Section not found' };
  const docId = String(section.rows[0].doc_id);
  if (c.claimedDocId != null && String(c.claimedDocId).toLowerCase() !== docId.toLowerCase()) {
    return { ok: false, status: 400, error: 'doc_id is not the document this section belongs to. Nothing was saved.' };
  }
  if (c.parentCommentId) {
    const parent = await client.query(
      'SELECT 1 FROM authoring_comments WHERE id::text = $1 AND section_id = $2 AND tenant_id = $3',
      [String(c.parentCommentId), c.sectionId, c.tenantId]
    );
    if ((parent.rowCount ?? 0) === 0) {
      return { ok: false, status: 400, error: 'The comment being replied to is not on this section. Nothing was saved.' };
    }
  }
  const result = await client.query(
    `INSERT INTO authoring_comments
     (id, section_id, doc_id, body, anchor, status, created_by, user_name, user_email,
      parent_comment_id, position_data, created_at, tenant_id)
     VALUES ($1, $2, $3, $4, $5, 'open', $6, $7, $8, $9, $10, NOW(), $11)
     RETURNING *`,
    [c.commentId, c.sectionId, docId, c.body, c.anchor, c.createdBy, c.userName, c.userEmail,
      c.parentCommentId, c.positionData, c.tenantId]
  );
  await createAuditTrail(
    req,
    docId,
    c.sectionId,
    c.parentCommentId ? 'reply_added' : 'comment_added',
    null,
    c.body,
    null,
    commentRecordMetadata(c.commentId, c.sectionId, c.parentCommentId, c.anchor, section.rows[0].content),
    client
  );
  return { ok: true, comment: result.rows[0] };
}

// POST /api/authoring/sections/:sectionId/comment - Add comment
// THE comment-creation endpoint. There used to be two: this one, which the
// editor calls (DocumentAuthoring.tsx:471), and a `POST /comments` that wrote
// the same table with a fuller row — author name and email, threading parent,
// anchor position — and then INSERTed into a `authoring_comment_activity`
// table that no migration creates, so it 500'd after the comment had already
// been written. Nothing called it.
//
// The duplicate is gone and its capability moved here rather than being
// dropped with it: the read path GET /documents/:id/comments selects
// user_name, user_email, parent_comment_id and position_data, and renders
// `COALESCE(c.user_name, c.created_by) AS author_name` — so with only the thin
// write, every comment in the UI was attributed to a raw actor id and no reply
// could ever be threaded.
router.post('/sections/:sectionId/comment', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { body, anchor, doc_id, parent_comment_id, position_data } = req.body;
    const tenantId = getTenantId(req);
    const commentId = crypto.randomUUID();
    // Identity from the VERIFIED JWT only — never from a header or the body.
    const createdBy = getActorId(req);
    if (!createdBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }
    const userEmail = req.user?.email ?? null;
    const userName = userEmail || createdBy;

    if (!body) {
      return res.status(400).json({
        success: false,
        error: 'Comment body is required',
      });
    }

    /* The comment and its record commit together, or neither does (D5,
       2026-09-26). This used to INSERT on the pool in autocommit and then
       write the audit row separately through the legacy wrapper — with no
       body, the reason "Legacy audit event" and the actor lost, so the
       inspector's ledger showed the comment as made by "System", and a failed
       audit write left a comment nobody had recorded. The comment belongs to
       the document its SECTION belongs to: a body doc_id that disagrees is
       refused rather than overridden, so a client bug surfaces, and a parent
       must be a comment on this same section (SEC-A-2, periodic review
       2026-09-28). */
    const written = await inTransaction((client) =>
      writeAttributedComment(client, req, {
        commentId,
        sectionId: String(sectionId),
        tenantId,
        body: String(body),
        anchor,
        claimedDocId: doc_id,
        parentCommentId: parent_comment_id ?? null,
        positionData: position_data ?? null,
        createdBy,
        userName,
        userEmail,
      })
    );
    if (!written.ok) return res.status(written.status).json({ success: false, error: written.error });
    const created = written.comment;

    res.status(201).json({
      success: true,
      comment: created,
      message: 'Comment added successfully',
    });
  } catch (error) {
    console.error('Error adding comment:', error);
    return serverError(res, logger, 'saving comment', error);
  }
});

/**
 * The record of a comment's status change, written with the REAL request: the
 * legacy wrapper this used rebuilt a request with no user id, so the chained
 * row had no actor and the ledger showed a person's resolution as "System".
 * The resolution note is the person's stated reason for closing the thread;
 * before and after content are the previous and new notes.
 */
async function recordCommentStatusChange(
  client: Queryable,
  req: Request,
  change: {
    commentId: string;
    status: unknown;
    before: { status: string; resolution_note: string | null };
    updated: { doc_id: string | null; section_id: string; status: string; resolution_note: string | null };
  },
): Promise<void> {
  const { commentId, status, before, updated } = change;
  const transition =
    status === 'resolved' ? 'resolved' : status === 'open' ? 'reopened' : status ? String(status) : 'note';
  await createAuditTrail(
    req,
    updated.doc_id ?? undefined,
    updated.section_id,
    status === 'resolved' ? 'comment_resolved' : 'comment_updated',
    before.resolution_note ?? null,
    updated.resolution_note ?? null,
    status === 'resolved' ? (updated.resolution_note ?? null) : null,
    {
      comment_id: commentId,
      section_id: updated.section_id,
      transition,
      previous_status: before.status,
      status: updated.status,
      previous_resolution_note: before.resolution_note ?? null,
      resolution_note: updated.resolution_note ?? null,
    },
    client
  );
}

/** The SET clauses and their values for a comment status change; empty when nothing changes. */
function commentStatusUpdate(
  status: unknown,
  resolutionNote: unknown,
  resolver: string,
): { updates: string[]; values: unknown[] } {
  const updates: string[] = [];
  const values: unknown[] = [];
  const param = (v: unknown) => `$${values.push(v)}`;
  if (status) {
    updates.push(`status = ${param(status)}`);
    if (status === 'resolved') {
      updates.push(`resolved_at = NOW(), resolved_by = ${param(resolver)}`);
      // The resolution RECORD is this resolution's, whole: a re-resolve
      // without a stated reason must not display the PREVIOUS resolver's
      // note under the new resolver's name. The prior resolution stays in
      // the audit ledger; the row carries only the current one.
      updates.push(`resolution_note = ${param(resolutionNote || null)}`);
    } else if (status === 'open') {
      // Reopen clears the resolution fields — the row reflects CURRENT
      // state ("this thread is open"), and the who/when/why of the earlier
      // resolution lives in the audit trail, not on an open thread.
      updates.push('resolved_at = NULL, resolved_by = NULL, resolution_note = NULL');
    }
  } else if (resolutionNote) {
    updates.push(`resolution_note = ${param(resolutionNote)}`);
  }
  return { updates, values };
}

// PATCH /api/authoring/comments/:commentId - Update comment status
router.patch('/comments/:commentId', async (req: Request, res: Response) => {
  try {
    const { commentId } = req.params;
    const { status, resolution_note } = req.body;
    const tenantId = getTenantId(req);
    const resolvedBy = getActorId(req);
    if (!resolvedBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    const validStatuses = ['open', 'resolved', 'dismissed', 'in_review'];
    if (status && !validStatuses.includes(status)) {
      return res.status(400).json({
        success: false,
        error: `Invalid status. Must be one of: ${validStatuses.join(', ')}`,
      });
    }

    // The same principal convention comment CREATION records (user_name =
    // verified email, falling back to the actor id): the rail displays this
    // value, and "Resolved by 1" is an attribution no reader can use. Still
    // JWT-sourced either way — never a header, never the body.
    const { updates, values } = commentStatusUpdate(status, resolution_note, req.user?.email ?? resolvedBy);
    const paramCount = values.length;

    if (updates.length === 0) {
      // An empty body used to build `SET  WHERE id = $1` — malformed SQL
      // answered as a 500 with the driver's message in the payload.
      return res.status(400).json({ success: false, error: 'No comment changes supplied' });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      const before = await client.query(
        `SELECT doc_id, section_id, status, resolution_note
           FROM authoring_comments
          WHERE id = $1 AND tenant_id = $2
          FOR UPDATE`,
        [commentId, tenantId]
      );
      if (((before.rowCount ?? 0) === 0)) {
        await client.query('ROLLBACK');
        return res.status(404).json({ success: false, error: 'Comment not found' });
      }

      values.push(commentId, tenantId);
      const result = await client.query(
        `UPDATE authoring_comments
            SET ${updates.join(', ')}, updated_at = NOW()
          WHERE id = $${paramCount + 1} AND tenant_id = $${paramCount + 2}
          RETURNING *`,
        values
      );

      const updated = result.rows[0];
      await recordCommentStatusChange(client, req, {
        commentId: String(commentId),
        status,
        before: before.rows[0],
        updated,
      });

      await client.query('COMMIT');
      res.json({
        success: true,
        comment: updated,
        message: 'Comment updated successfully',
      });
    } catch (error) {
      await client.query('ROLLBACK').catch(() => undefined);
      throw error;
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Error updating comment:', error);
    return serverError(res, logger, 'updating comments', error);
  }
});

// ============= Citations & Data Tokens =============

/* ── Every citation write is on the document's trail, in its transaction ────
   A citation records what a section was drafted from, and its payload_sha256
   the source's checksum at the moment it was cited: the value the Sources rail
   compares against today. No citation write (cite, cite-source, the uncite
   DELETE, refresh-token, refresh-all) wrote an audit row, and the DELETE and
   the overwrites destroyed the cite-time value with no before-image anywhere
   (periodic review 2026-09-28, editor family, P11-A-1 / SEC-A-8). Each now
   writes its row on the same client as the change, carrying the citation as it
   stood before and after, so the prior value survives and an audit write that
   fails takes the change with it. The document is read from the section row,
   never from the URL or the body: the section the guard authorised is the one
   the trail names. */
type CitationAuditOperation = 'CITATION_ADDED' | 'CITATION_UPDATED' | 'CITATION_REMOVED' | 'CITATION_REFRESHED';

const citationJson = (image: CitationImage | null): string | null => (image ? JSON.stringify(image) : null);

async function auditCitationWrite(
  req: Request,
  client: Queryable,
  entry: { sectionId: string; operation: CitationAuditOperation; change: CitationChange; reason: string },
): Promise<void> {
  const section = await client.query(
    'SELECT doc_id FROM authoring_sections WHERE id = $1 AND tenant_id = $2',
    [entry.sectionId, getTenantId(req)]
  );
  const docId = section.rows[0]?.doc_id;
  // Unreachable behind the section guard. Refused rather than written with no
  // document, where no document's trail would ever show it.
  if (docId == null) throw new Error('Citation audit: the section is not in this organization');
  const { before, after } = entry.change;
  const cited = (after ?? before) as CitationImage;
  await createAuditTrail(
    req,
    String(docId),
    entry.sectionId,
    entry.operation,
    citationJson(before),
    citationJson(after),
    entry.reason,
    {
      citation_id: cited.id,
      source: cited.source,
      reference_id: cited.reference_id,
      previous_sha256: before ? before.payload_sha256 : null,
      sha256: after ? after.payload_sha256 : null,
    },
    client
  );
}

// POST /api/authoring/sections/:sectionId/cite - Add citation
router.post('/sections/:sectionId/cite', async (req: Request, res: Response) => {
  try {
    const sectionId = String(req.params.sectionId);
    const { source, anchor, citation_text, reference_id } = req.body;
    const tenantId = getTenantId(req);
    const citationId = crypto.randomUUID();
    const createdBy = getActorId(req);
    if (!createdBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }

    if (!source) {
      return res.status(400).json({
        success: false,
        error: 'Citation source is required',
      });
    }

    const citation = await inTransaction(async (client) => {
      if (source === 'cre_evidence_source') {
        const { citeSource } = await import('../services/clinical-regulatory-evidence/source-usage.service.js');
        const cited = await citeSource(tenantId, { sectionId, sourceId: reference_id, anchor, citationText: citation_text, createdBy }, client);
        if (cited.change) await auditCitationWrite(req, client, {
          sectionId, operation: cited.created ? 'CITATION_ADDED' : 'CITATION_UPDATED', change: cited.change,
          reason: cited.created ? 'Source cited' : 'Citation text changed',
        });
        const recorded = await client.query('SELECT * FROM authoring_citations WHERE id=$1 AND tenant_id=$2', [cited.citationId, tenantId]);
        return recorded.rows[0];
      }
      const result = await client.query(
        `INSERT INTO authoring_citations
         (id, section_id, source, anchor, citation_text, reference_id, created_by, created_at, tenant_id)
         VALUES ($1, $2, $3, $4, $5, $6, $7, NOW(), $8)
         RETURNING *`,
        [citationId, sectionId, source, anchor, citation_text, reference_id, createdBy, tenantId]
      );
      await auditCitationWrite(req, client, {
        sectionId,
        operation: 'CITATION_ADDED',
        change: { before: null, after: result.rows[0] },
        reason: 'Citation recorded',
      });
      return result.rows[0];
    });

    res.status(201).json({
      success: true,
      citation,
      message: 'Citation added successfully',
    });
  } catch (error) {
    if (replyCitationAccessRefusal(res, error)) return;
    const { SourceUsageError } = await import('../services/clinical-regulatory-evidence/source-usage.service.js');
    if (error instanceof SourceUsageError) return res.status(400).json({ success: false, error: error.message });
    console.error('Error adding citation:', error);
    return serverError(res, logger, 'saving cite', error);
  }
});

/** One HTTP boundary for current source/project admission on citation reads and writes. */
function replyCitationAccessRefusal(res: Response, error: unknown): boolean {
  if (!(error instanceof SourceReadAccessError || error instanceof ProgramReadAccessError)) return false;
  res.status(error.status).json({ success: false, error: error.code, message: error.message });
  return true;
}

// ── Canonical source citations ─────────────────────────────────────────────
// The Data Room holds canonical source identities; these endpoints are how a
// section records which of them it was drafted from, and how that record is read
// back. They go through source-usage.service so the convention
// (source = 'cre_evidence_source', reference_id = the source id,
// payload_sha256 = the source's checksum at cite time) is enforced server-side
// rather than trusted from the request body — POST /cite above takes `source` as
// free text, which is why nothing could ever be read back by source id.

// GET /api/authoring/sections/:sectionId/sources — what this section is written from
router.get('/sections/:sectionId/sources', async (req: Request, res: Response) => {
  let client: PoolClient | undefined;
  try {
    const tenantId = getTenantId(req);
    const { listSectionSources } = await import(
      '../services/clinical-regulatory-evidence/source-usage.service.js'
    );
    client = await pool.connect();
    // Checked-out clients receive their RLS scope after BEGIN; checkout alone
    // does not stamp tenant variables. Keep the complete read on that client.
    await client.query('BEGIN READ ONLY');
    const usages = await listSectionSources(tenantId, String(req.params.sectionId), {
      executor: client, userId: Number(getActorId(req)),
    });
    await client.query('COMMIT');
    res.json({ success: true, sectionId: String(req.params.sectionId), sources: usages });
  } catch (error) {
    await client?.query('ROLLBACK').catch(() => undefined);
    if (replyCitationAccessRefusal(res, error)) return;
    console.error('GET /sections/:sectionId/sources', error);
    res.status(500).json({ success: false, error: 'Failed to load section sources' });
  } finally {
    client?.release();
  }
});

// POST /api/authoring/sections/:sectionId/cite-source — record a source citation
router.post('/sections/:sectionId/cite-source', async (req: Request, res: Response) => {
  try {
    const tenantId = getTenantId(req);
    const createdBy = getActorId(req);
    if (!createdBy) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }
    const { citeSource, SourceUsageError } = await import(
      '../services/clinical-regulatory-evidence/source-usage.service.js'
    );
    const sectionId = String(req.params.sectionId);
    try {
      const result = await inTransaction(async (client) => {
        const cited = await citeSource(
          tenantId,
          {
            sectionId,
            sourceId: req.body?.source_id,
            citationText: req.body?.citation_text ?? null,
            anchor: req.body?.anchor ?? null,
            createdBy,
          },
          client
        );
        // A second cite of the same source writes nothing unless it brings new
        // citation text; it never re-reads the checksum (see citeSource).
        if (cited.change) {
          await auditCitationWrite(req, client, {
            sectionId,
            operation: cited.created ? 'CITATION_ADDED' : 'CITATION_UPDATED',
            change: cited.change,
            reason: cited.created ? 'Source cited' : 'Citation text changed',
          });
        }
        return cited;
      });
      // 201 on a new citation, 200 when the section already cited it — the
      // caller can tell whether it added a source or found one already there.
      return res.status(result.created ? 201 : 200).json({
        success: true,
        citationId: result.citationId,
        citedChecksum: result.citedChecksum,
        created: result.created,
      });
    } catch (e) {
      if (e instanceof SourceUsageError) {
        return res.status(400).json({ success: false, error: e.message });
      }
      throw e;
    }
  } catch (error) {
    if (replyCitationAccessRefusal(res, error)) return;
    console.error('POST /sections/:sectionId/cite-source', error);
    res.status(500).json({ success: false, error: 'Failed to record the source citation' });
  }
});

// DELETE /api/authoring/sections/:sectionId/cite-source/:sourceId — stop citing it
router.delete('/sections/:sectionId/cite-source/:sourceId', async (req: Request, res: Response) => {
  try {
    const tenantId = getTenantId(req);
    const { removeSourceCitation } = await import(
      '../services/clinical-regulatory-evidence/source-usage.service.js'
    );
    const sectionId = String(req.params.sectionId);
    const removed = await inTransaction(async (client) => {
      const rows = await removeSourceCitation(tenantId, sectionId, String(req.params.sourceId), client);
      // The deleted row is the before-image: the only record left of what the
      // section cited, and against which checksum.
      for (const row of rows) {
        await auditCitationWrite(req, client, {
          sectionId,
          operation: 'CITATION_REMOVED',
          change: { before: row, after: null },
          reason: 'Citation removed',
        });
      }
      return rows.length;
    });
    if (removed === 0) {
      return res.status(404).json({
        success: false,
        error: 'No removable citation of that source on this section (a frozen citation is immutable)',
      });
    }
    res.json({ success: true, removed: true });
  } catch (error) {
    console.error('DELETE /sections/:sectionId/cite-source/:sourceId', error);
    res.status(500).json({ success: false, error: 'Failed to remove the source citation' });
  }
});

