// GET /api/authoring/documents/:id/comments - Get all comments for document
router.get('/documents/:id/comments', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const tenantId = getTenantId(req);
    const { status, author, includeReplies = 'true' } = req.query;

    let query = `
      SELECT
        c.id, c.doc_id, c.section_id, c.body, c.anchor, c.status, c.created_by, c.user_name, c.user_email, c.parent_comment_id, c.position_data, c.resolution_note, c.resolved_by, c.resolved_at, c.created_at, c.updated_at, c.tenant_id,
        COALESCE(c.user_name, c.created_by) as author_name,
        c.user_email as author_email,
        COUNT(DISTINCT r.id) as reply_count,
        s.code as section_code,
        s.title as section_title
      FROM authoring_comments c
      LEFT JOIN authoring_sections s ON c.section_id = s.id
      LEFT JOIN authoring_comments r ON r.parent_comment_id = c.id
      WHERE c.doc_id = $1 AND c.tenant_id = $2
    `;

    const params: any[] = [id, tenantId];
    let paramIndex = 3;

    if (status) {
      query += ` AND c.status = $${paramIndex}`;
      params.push(status);
      paramIndex++;
    }

    if (author) {
      query += ` AND c.created_by = $${paramIndex}`;
      params.push(author);
      paramIndex++;
    }

    // Only get top-level comments by default
    if (includeReplies === 'false') {
      query += ` AND c.parent_comment_id IS NULL`;
    }

    query += ` GROUP BY c.id, s.code, s.title ORDER BY c.created_at DESC`;

    const result = await pool.query(query, params);

    // If includeReplies is true, fetch replies for each comment
    let comments = result.rows;
    if (includeReplies === 'true') {
      for (const comment of comments) {
        if (!comment.parent_comment_id) {
          const repliesResult = await pool.query(
            `SELECT
              c.id, c.doc_id, c.section_id, c.body, c.anchor, c.status, c.created_by, c.user_name, c.user_email, c.parent_comment_id, c.position_data, c.resolution_note, c.resolved_by, c.resolved_at, c.created_at, c.updated_at, c.tenant_id,
              COALESCE(c.user_name, c.created_by) as author_name,
              c.user_email as author_email
             FROM authoring_comments c
             WHERE c.parent_comment_id = $1 AND c.tenant_id = $2
             ORDER BY c.created_at ASC`,
            [comment.id, tenantId]
          );
          comment.replies = repliesResult.rows;
        }
      }
      // Filter out replies from top level
      comments = comments.filter(c => !c.parent_comment_id);
    }

    res.json({
      success: true,
      comments,
      total: comments.length,
    });
  } catch (error) {
    console.error('Error fetching comments:', error);
    return serverError(res, logger, 'loading comments', error);
  }
});

/* PUT /comments/:id and DELETE /comments/:id are DELETED, not moved. Neither
 * was reachable from the client (the rail's only status writer is
 * PATCH /comments/:id), and both let any authenticated tenant member rewrite
 * or hard-delete ANY user's review comment: the PUT updated `body` in place
 * with no prior-text capture anywhere (the audit event logged that an edit
 * happened, never what changed), and the DELETE removed the row and its
 * replies for good with only the comment id in the ledger — the reviewer's
 * actual words unrecoverable even from the audit trail. Review history is
 * immutable here: threads are resolved or reopened through PATCH (verified
 * resolver, resolved_at, note kept), never rewritten, never erased. If
 * retraction is ever wanted, it is a tombstone that retains and renders the
 * original content as retracted — a new capability, not these routes. */

/** The native review service receives only the verified actor and pinned tenant client. */
function peerReviewInput(req: Request) {
  const actorId = getActorId(req);
  if (!actorId) throw new AuthoringPeerReviewRefused(401, 'REVIEW_ACTOR_REQUIRED', 'Authentication required.');
  const documentId = req.params.id;
  if (typeof documentId !== 'string' || !isUuid(documentId)) {
    throw new AuthoringPeerReviewRefused(400, 'REVIEW_DOCUMENT_INVALID', 'A valid document identifier is required.');
  }
  return { tenantId: getTenantId(req), actorId, documentId: documentId.toLowerCase() };
}

function peerReviewAudit(req: Request) {
  return { ipAddress: req.ip || req.connection?.remoteAddress || 'unknown',
    userAgent: req.headers['user-agent'] || 'unknown' };
}

function peerReviewFailure(res: Response, error: unknown): Response {
  if (error instanceof AuthoringPeerReviewCommitUnconfirmed) return res.status(503).json({ success: false,
    error: { code: 'REVIEW_COMMIT_UNCONFIRMED', message: 'The review write could not be confirmed. Reload the document and review request before trying again.' } });
  if (!(error instanceof AuthoringPeerReviewRefused) || error.status === 503) {
    logger.error('Authoring peer review could not be verified', { error });
    return res.status(503).json({ success: false,
      error: { code: 'REVIEW_UNAVAILABLE', message: 'The review could not be verified. Reload before trying again.' } });
  }
  if (error.status === 409 && error.code === 'REVIEWER_IS_AUTHOR') return res.status(409).json(REVIEWER_IS_AUTHOR_REFUSAL);
  return res.status(error.status).json({ success: false, error: { code: error.code, message: error.message } });
}

function validPeerReviewers(reviewers: unknown): reviewers is Array<{ id: string | number; name?: string; email?: string }> {
  if (!Array.isArray(reviewers) || !reviewers.length) return false;
  const ids = new Set<string>();
  return reviewers.every(r => {
    if (!r || !(typeof r.id === 'string' && r.id.trim() || Number.isSafeInteger(r.id) && r.id > 0)) return false;
    if (r.name !== undefined && typeof r.name !== 'string' || r.email !== undefined && typeof r.email !== 'string') return false;
    const id = String(r.id).trim();
    if (ids.has(id)) return false;
    ids.add(id); return true;
  });
}

// GET /api/authoring/documents/:id/reviews - Read the complete saved review context.
router.get('/documents/:id/reviews', async (req: Request, res: Response) => {
  try { return res.json(await readAuthoringPeerReviews(requestConnectable(req), peerReviewInput(req))); }
  catch (error) { return peerReviewFailure(res, error); }
});

type ReviewTaskLedgerRow = import('../services/tasking/task-audit').AuditTaskActionParams;
type ReviewTaskNotice = import('../services/tasking/task-side-effects').TaskEventNotice;

/** What a verdict did to its reviewer's review tasks on the document. */
interface VerdictTaskClosure {
  /** Completed by the verdict, in task-id order. */
  completed: string[];
  /** Left open, and why: completing it needs the reviewer's signature, or its predecessors are not done. */
  leftOpen: Array<{ taskId: string; why: 'signature-required' | 'blocked' }>;
  /** Sent once the verdict has committed. */
  notices: ReviewTaskNotice[];
  /** Writes the tasks' ledger rows; called after the verdict's own audit row. */
  record: () => Promise<void>;
}

/**
 * A reviewer's verdict completes their open review tasks on the same document,
 * on the verdict's own transaction (wave 2D; outside-file request E of wave 2C,
 * docs/evidence/D2-ONE-ANA/2026-10-08/ana-2d-review-loop-closes/).
 *
 * The verdict lives in authoring_reviews. The reviewer's My work task lives in
 * unified_tasks: SendForReviewDialog.tsx creates it with sourceEntityType
 * 'authoring_document', sourceEntityId <docId>, taskType 'review' and the
 * reviewer as assignee. Nothing joined the two, so a verdict left its task open
 * and the Tasks rail could only reconcile them on screen. The task now moves
 * through the tasking path's own audited transition, composed as
 * PATCH /api/regulatory/tasks/:id/status composes it: the state machine
 * (isLegalTransition), the canonical status write
 * (unifiedTaskService.updateTaskStatus, a compare-and-set), the completion
 * cascade (cascadeUnblockOnCompletionInTx) and one `task.transition` lineage
 * row per move (auditTaskActionInTx). Nothing here writes a task column itself.
 * The verdict, the task and their ledger rows commit together, or none of them
 * does.
 *
 * Two phases, for lock order. Every task row lock (the task, then its
 * dependents) is taken here, before the verdict's own audit row takes the
 * audit-chain lock: the one order every task transaction uses
 * (taskManagement.routes.ts). The ledger rows are written by `record`, after
 * the verdict's row, so the trail shows the verdict before the task it closed.
 *
 * What it does not do:
 *   - an approval-gated task that is not yet approved is left open. Completing
 *     it is the reviewer's §11.50 signature, and a verdict is not one. The
 *     Tasks rail offers Complete once the verdict exists, and the server takes
 *     the signature there.
 *   - a blocked task is left open: its predecessors are not complete.
 *   - a pending task is started, then completed. The state machine has no
 *     pending → completed move, and each step gets its own ledger row.
 *   - a reviewer id that is not a users.id integer has no task (assignee_id is
 *     an integer column), so nothing is looked up.
 */
async function closeReviewTasksOnVerdict(
  client: Queryable,
  v: { tenantId: number; docId: string; reviewerId: string; verdict: string; reviewId: string; reason: string | null },
): Promise<VerdictTaskClosure> {
  const closure: VerdictTaskClosure = { completed: [], leftOpen: [], notices: [], record: async () => undefined };
  const actor = /^[1-9][0-9]*$/.test(v.reviewerId) ? Number(v.reviewerId) : NaN;
  if (!Number.isSafeInteger(actor)) return closure;

  const [{ drizzle }, schema, orm, { default: unifiedTaskService }, { isLegalTransition }, sideEffects, { auditTaskActionInTx }] =
    await Promise.all([
      import('drizzle-orm/node-postgres'),
      import('../../shared/schema'),
      import('drizzle-orm'),
      import('../services/unifiedTaskService'),
      import('../services/tasking/task-state-machine'),
      import('../services/tasking/task-side-effects'),
      import('../services/tasking/task-audit'),
    ]);
  const { unifiedTasks } = schema;
  // Drizzle over this transaction's own client: every read, write and ledger
  // row below runs on the verdict's connection.
  const tx = drizzle(client as never, { schema });
  const open = await tx
    .select({
      taskId: unifiedTasks.taskId,
      status: unifiedTasks.status,
      title: unifiedTasks.title,
      createdById: unifiedTasks.createdById,
      approvalRequired: unifiedTasks.approvalRequired,
      approvalStatus: unifiedTasks.approvalStatus,
    })
    .from(unifiedTasks)
    .where(orm.and(
      orm.eq(unifiedTasks.organizationId, v.tenantId),
      orm.eq(unifiedTasks.sourceEntityType, 'authoring_document'),
      orm.eq(unifiedTasks.sourceEntityId, v.docId),
      orm.eq(unifiedTasks.taskType, 'review'),
      orm.eq(unifiedTasks.assigneeId, actor),
      orm.isNull(unifiedTasks.deletedAt),
      orm.inArray(unifiedTasks.status, ['pending', 'in-progress', 'review', 'blocked']),
    ))
    .orderBy(unifiedTasks.taskId)
    .for('no key update');

  const ledger: ReviewTaskLedgerRow[] = [];
  const cause = { cause: 'review-verdict', verdict: v.verdict, reviewId: v.reviewId, docId: v.docId };
  for (const t of open) {
    if (t.approvalRequired === true && t.approvalStatus !== 'approved') {
      closure.leftOpen.push({ taskId: t.taskId, why: 'signature-required' });
      continue;
    }
    const steps = isLegalTransition(t.status, 'completed') ? ['completed'] : t.status === 'pending' ? ['in-progress', 'completed'] : null;
    if (!steps) {
      closure.leftOpen.push({ taskId: t.taskId, why: 'blocked' });
      continue;
    }
    let from = t.status;
    for (const to of steps) {
      const moved = await unifiedTaskService.updateTaskStatus(t.taskId, to, actor, { organizationId: v.tenantId, expectedStatus: from }, tx);
      // The row is locked above, so a lost compare-and-set is a defect, not a
      // race: it rolls the verdict back with it.
      if (!moved) throw new Error(`Review task ${t.taskId} did not move from ${from} to ${to} under its lock.`);
      ledger.push({
        orgId: v.tenantId,
        userId: actor,
        command: 'task.transition',
        taskId: t.taskId,
        payload: { from, to, ...cause },
        // The reason the reviewer stated with the verdict (none for an approval
        // given without one), never a sentence composed here.
        reason: v.reason,
        summary: to === 'completed' ? 'Completed by the reviewer’s verdict on the document' : 'Started by the reviewer’s verdict on the document',
      });
      from = to;
    }
    const cascade = await sideEffects.cascadeUnblockOnCompletionInTx(v.tenantId, t.taskId, { tx, actorUserId: actor });
    ledger.push(...cascade.ledger);
    closure.notices.push(...cascade.notices);
    if (t.createdById && t.createdById !== actor) {
      closure.notices.push({ organizationId: v.tenantId, recipientUserId: t.createdById, category: 'task_completed', title: `Completed: ${t.title}`, taskId: t.taskId });
    }
    closure.completed.push(t.taskId);
  }
  closure.record = async () => {
    for (const entry of ledger) await auditTaskActionInTx(tx, entry);
  };
  return closure;
}

// POST /api/authoring/documents/:id/review - Record an assigned, saved-content-bound verdict.
router.post('/documents/:id/review', async (req: Request, res: Response) => {
  try {
    const body = authoringReviewInputSchema.safeParse(req.body);
    if (!body.success) return res.status(400).json({ success: false,
      error: { code: 'REVIEW_INPUT_INVALID', message: 'A verdict and the exact saved review context are required.' } });
    const saved = await submitAuthoringPeerReview(requestConnectable(req), { ...peerReviewInput(req), body: body.data },
      { audit: peerReviewAudit(req), closeTasks: closeReviewTasksOnVerdict });
    if (saved.tasks.notices.length) {
      const { notifyTaskEvent } = await import('../services/tasking/task-side-effects');
      for (const notice of saved.tasks.notices) notifyTaskEvent(notice);
    }
    return res.json({ success: true, review: saved.review,
      tasks: { completed: saved.tasks.completed, leftOpen: saved.tasks.leftOpen }, auditTrail: saved.auditTrail });
  } catch (error) { return peerReviewFailure(res, error); }
});

// POST /api/authoring/documents/:id/request-review - Request review from users
/** The pool the permission helpers take; a transaction client answers the same queries. */
/** Whether each requested reviewer was granted review access, and why not. */
type ReviewGrantOutcome =
  | { reviewerId: string; granted: true; permissionId: string }
  | { reviewerId: string; granted: false; reason: string };

/**
 * The reviewer named in a review request gets what reviewing needs: the
 * REVIEWER role on the document (view, comment, review — and, with a signing
 * role in the organization, the review e-signature). QA 2026-10-08 (j4): a
 * request granted nothing and the grant API had no caller, so the person asked
 * to review could do neither. Granted only by someone who may manage the
 * document's access — its owner or an administrator, the rule
 * POST /docs/:docId/permissions applies — on the caller's transaction, with a
 * chained ledger row per grant. Anyone else's request is recorded and the
 * answer says no grant was made.
 */
async function grantRequestedReviewers(args: {
  client: Queryable;
  req: Request;
  docId: string;
  tenantId: number;
  scope: Awaited<ReturnType<typeof resolveAuthoringDocumentScope>>;
  principal: ReturnType<typeof authoringPrincipalFromRequest>;
  reviews: Array<{ id: string; reviewer_id: string | number; reviewer_email?: string | null }>;
  reason: string | null;
}): Promise<ReviewGrantOutcome[]> {
  const { client, req, docId, tenantId, scope, principal, reviews, reason } = args;
  const manage = scope && principal
    ? await decideAuthoringPermission({ pool: client, principal, scope, action: 'manage_permissions' })
    : null;
  if (!manage?.allowed || !principal) {
    return reviews.map((r) => ({
      reviewerId: String(r.reviewer_id),
      granted: false as const,
      reason:
        'No review access was granted: only the document’s owner or an administrator grants access to it. ' +
        'Ask one of them to grant this reviewer the Reviewer role.',
    }));
  }
  const grants: ReviewGrantOutcome[] = [];
  for (const review of reviews) {
    const reviewerId = String(review.reviewer_id);
    const permission = await grantAuthoringPermission({
      pool: client,
      tenantId,
      docId,
      principalId: reviewerId,
      email: review.reviewer_email ?? null,
      role: 'REVIEWER',
      grantedBy: principal.id,
      reason: `Review requested${reason ? `: ${reason}` : ''}`,
    });
    await writeChainedAuditRow(client, {
      tenantId,
      userId: getActorId(req) ?? undefined,
      action: 'authoring.permission.grant',
      resourceType: 'authoring_document_permission',
      resourceId: String(permission.id),
      ipAddress: (req.ip ?? undefined) as string | undefined,
      userAgent: req.headers['user-agent'] as string | undefined,
      details: { docId, principalId: reviewerId, role: 'REVIEWER', via: 'request-review', reviewId: review.id },
    });
    grants.push({ reviewerId, granted: true, permissionId: String(permission.id) });
  }
  return grants;
}

/** The refusal for a review request that names the document's author. */
const REVIEWER_IS_AUTHOR_REFUSAL = {
  success: false,
  error: {
    code: 'REVIEWER_IS_AUTHOR',
    message: 'The author of a document cannot review it. Choose someone else as the reviewer. Nothing was requested.',
  },
  field: 'reviewers',
} as const;

router.post('/documents/:id/request-review', async (req: Request, res: Response) => {
  try {
    const { reviewers } = req.body;
    if (!validPeerReviewers(reviewers)) return res.status(400).json({ success: false,
      error: 'reviewers must be a non-empty array of distinct reviewer identities with valid optional name and email fields' });
    const stated = optionalGovernedReason(req.body?.reason);
    if (!stated.ok) return res.status(400).json({ success: false, error: stated.error, field: 'reason' });
    const input = peerReviewInput(req);
    const saved = await requestAuthoringPeerReviews(requestConnectable(req), { ...input, reviewers, reason: stated.reason }, {
      audit: peerReviewAudit(req),
      grant: (client, current) => grantRequestedReviewers({ client, req, docId: input.documentId,
        tenantId: input.tenantId, scope: current.scope, principal: current.actor.principal,
        reviews: current.reviews.map(review => ({ id: review.id, reviewer_id: review.reviewer_id,
          reviewer_email: typeof review.reviewer_email === 'string' ? review.reviewer_email : null })), reason: current.reason }),
    });
    return res.json({ success: true, ...saved, message: `Review requested from ${reviewers.length} reviewer(s)` });
  } catch (error) { return peerReviewFailure(res, error); }
});

// ============= AI Integration =============

async function readDraftAssemblySources(q: Queryable, identity: { organizationId: number; userId: number; programId: unknown },
  raw: unknown, options: { lock?: boolean; invalidStatus?: 400 | 409 } = {}) {
  const { readSelectedAuthoringSources, AssemblySourceError } = await import('../services/authoring/authoring-assembly-sources');
  const manifest = readAssemblySourceManifest(raw);
  if (!manifest) throw new AssemblySourceError(options.invalidStatus ?? 400, 'ASSEMBLY_SOURCES_INVALID', 'The selected source receipt is invalid. Select the sources again before drafting.');
  if (typeof identity.programId !== 'string' || manifest.programId.toLowerCase() !== identity.programId.toLowerCase()) {
    throw new AssemblySourceError(409, 'ASSEMBLY_SOURCES_CHANGED', 'The selected sources do not belong to this document project. Select the sources again.');
  }
  return readSelectedAuthoringSources(q, { ...identity, programId: identity.programId },
    manifest.entries.map(entry => entry.source), { expectedManifest: manifest, lock: options.lock });
}

async function reserveDraftAssemblySources(q: Queryable, identity: { organizationId: number; userId: number; sectionId: string }, raw: unknown) {
  const parent = await q.query(`SELECT to_jsonb(d)->>'client_program_id' AS program_id
    FROM authoring_sections s JOIN authoring_documents d ON d.id=s.doc_id AND d.tenant_id=s.tenant_id
    WHERE s.id=$1 AND s.tenant_id=$2`, [identity.sectionId, identity.organizationId]);
  return readDraftAssemblySources(q, { organizationId: identity.organizationId, userId: identity.userId,
    programId: parent.rows[0]?.program_id }, raw, { lock: true, invalidStatus: 409 });
}

function assemblySourceErrorDetails(error: unknown) {
  const failure = error as { status?: number; code?: string; message?: string } | null;
  if (!failure || typeof failure.code !== 'string' || !failure.code.startsWith('ASSEMBLY_SOURCES_') ||
      ![400, 403, 404, 409, 503].includes(failure.status ?? 0)) return null;
  return { status: failure.status!, code: failure.code, message: failure.message };
}

function draftAcceptUnconfirmed(res: Response) {
  return res.status(503).json({ success: false, error: { code: 'DRAFT_ACCEPT_UNCONFIRMED',
    message: 'The server could not confirm whether this draft was accepted. Check the exact saved section before another acceptance.' } });
}

// POST /api/authoring/sections/:sectionId/ai/draft - Generate AI draft
router.post('/sections/:sectionId/ai/draft', async (req: Request, res: Response) => {
  /* The turn this draft is (RT-6, AnA reasoning round 12): one record, opened
     before the model is asked and filed however the request ends, as the
     conversation's turns are (services/ana/turn-record.ts). */
  let draftTurn: DraftTurn | null = null;
  try {
    const { sectionId } = req.params;
    const { tone = 'professional', region = 'FDA', context, requirements } = req.body;
    const tenantId = getTenantId(req);

    // Get section details
    const sectionResult = await pool.query(
      `SELECT s.id, s.doc_id, s.code, s.title, s.content, s.order_index, s.track_changes, s.created_at, s.updated_at,
              s.updated_at::text AS base_updated_at, s.tenant_id, d.module, d.product_code,
              to_jsonb(d)->>'client_program_id' AS client_program_id
       FROM authoring_sections s
       JOIN authoring_documents d ON d.id = s.doc_id AND d.tenant_id = s.tenant_id
       WHERE s.id = $1 AND s.tenant_id = $2`,
      [sectionId, tenantId]
    );

    if (((sectionResult.rowCount ?? 0) === 0)) {
      return res.status(404).json({
        success: false,
        error: 'Section not found',
      });
    }

    const section = sectionResult.rows[0];
    // Project evidence belongs to the document's saved project, never a caller
    // field or the rest of the organization's projects. Admission re-reads the
    // actor's membership and sharing policy for this generation request.
    const projectScope = section.client_program_id == null ? null : await admitAnaProjectScope(pool, {
      organizationId: tenantId,
      userId: Number(getActorId(req)),
      projectRef: section.client_program_id,
    });
    const sourceIdentity = { organizationId: tenantId, userId: Number(getActorId(req)), programId: section.client_program_id };
    const selectedSources = Object.hasOwn(req.body ?? {}, 'sources')
      ? await readDraftAssemblySources(requestConnectable(req), sourceIdentity, req.body.sources) : null;
    const assemblySources = selectedSources?.manifest;

    // ── Retrieve this document's program Vault evidence ──────────────
    let evidenceBlock = '';
    let sourcesRetrieved = 0;
    /** Whether Data Room retrieval ran, and what it found. 'empty' (ran, found
     *  nothing) and 'failed' (did not run to completion) are different facts
     *  and only one of them says anything about the corpus. */
    let retrievalStatus: 'ok' | 'empty' | 'failed' = 'empty';
    let retrievalError: string | null = null;
    // The chunks this draft is retrieved from, captured so the accept endpoint can
    // record verified source spans against them (source-attribution Phase 3). Each
    // carries the canonical capture key when the exact Vault bytes resolve to
    // a cre_evidence_sources.id; that key is verified again below — at the
    // generation boundary, which holds the numeric orgId the resolver needs. Read
    // defensively (best-effort): a build without the retrieval enrichment simply
    // leaves sourceId null and the draft is still attributed honestly (all author).
    const retrievedChunks: Array<{ content: string; title: string; sourceId: string | null }> = [];
    let vaultSourceReceipt: import('../services/authoring/authoring-draft-sources.js').SectionDraftSourceReceipt | undefined;
    try {
      if (!projectScope?.projectId) throw new Error('This document has no verified project scope. No Data Room sources were read.');
      const searchQuery = `${section.module} ${section.code} ${section.title} ${
        section.product_code || ''
      }`.trim();
      // The session's tenant key. This search used to pass none, so it ranked
      // every tenant's Data Room atoms wherever RLS was not filtering — a CTD
      // section draft could cite another sponsor's evidence. No key is a failed
      // retrieval, reported as one below, never an unscoped search.
      const orgUuid = selectedSources ? null : await currentTenantOrgUuid(pool);
      if (!selectedSources && !orgUuid) throw new TenantKeyRequiredError('no tenant key for this session');
      // F03: the document's saved program determines the canonical Vault
      // corpus. There is no organization-wide atom fallback for absent scope.
      const retrieved = selectedSources ?? await (await import('../services/authoring/authoring-draft-sources.js')).retrieveSectionDraftSources({
        executor: requestConnectable(req), userId: Number(getActorId(req)), organizationId: tenantId,
        organizationUuid: orgUuid, programId: section.client_program_id, query: searchQuery });
      const searchResults = retrieved.chunks;
      if ('receipt' in retrieved) vaultSourceReceipt = retrieved.receipt;
      if (searchResults.length > 0) {
        sourcesRetrieved = searchResults.length;
        for (const r of searchResults as any[]) {
          retrievedChunks.push({
            content: typeof r.content === 'string' ? r.content : '',
            title: typeof r.title === 'string' ? r.title : '',
            sourceId: typeof r.sourceId === 'string' ? r.sourceId : null,
          });
        }
        evidenceBlock =
          '\n\n--- PROJECT DATA ROOM EVIDENCE (cite as [SRC-n]; not organization reference material) ---\n' +
          searchResults
            .map((r: any, i: number) => {
              const content = assemblySources ? r.content :
                r.content.length > 600 ? r.content.substring(0, 600) + '…' : r.content;
              return `[SRC-${i + 1}] "${r.title}"\n${content}`;
            })
            .join('\n\n') +
          '\n--- END EVIDENCE ---\n\n' +
          'Record which sources you used ONLY through the structured "attributions" ' +
          'field requested below — do NOT put [SRC-n] markers in the drafted prose, ' +
          'and never cite a source not shown above.';
        retrievalStatus = 'ok';
      } else {
        // Retrieval RAN and the corpus had nothing above threshold. Distinct
        // from a failure: here we know there is no evidence, which is itself a
        // fact about the Data Room.
        retrievalStatus = 'empty';
      }
    } catch (e: any) {
      if (selectedSources) throw e;
      /* A failed retrieval used to warn to the console and continue, leaving
         `sourcesRetrieved = 0` — indistinguishable from "the corpus had
         nothing". The model then drafted with no evidence block and the
         response said "AI draft generated successfully". So the one case where
         a reviewer most needs to know the draft is ungrounded looked exactly
         like the ordinary case. Recorded and reported instead. */
      retrievalStatus = 'failed';
      retrievalError = e?.message ? String(e.message).slice(0, 300) : 'unknown error';
      console.warn('[Authoring] Data Room retrieval failed (non-fatal):', retrievalError);
    }

    // ── Generate with the AI gateway. There is no other source of a draft. ──
    //
    // This route used to fall through to a hardcoded section skeleton when no
    // provider was enabled or the model call failed, answering HTTP 200
    // `success:false, degraded:true, source:'template'` with a full template
    // body — and the client rendered it as a draft (VSR-001 §8 F-10). A
    // deployment with no enabled provider is refused with 503
    // GATEWAY_UNAVAILABLE, the same code AnA answers with, and NO draft body;
    // a gateway failure is refused with its own classified code; a fault of
    // ours is a 500. Nothing on this path fabricates content (URS-AUTH-012;
    // working agreement: fail closed, never fabricate).
    const { getGateway } = await import('../services/ai-gateway/gateway.js');
    const { GATEWAY_ERROR_HTTP_STATUS, classifyGatewayError, isGatewayError } = await import(
      '../services/ai-gateway/gateway-error-map.js'
    );
    const gw = getGateway();
    if (gw.getEnabledProviders().length === 0) {
      logger.warn('ai/draft refused: no AI provider is enabled on the gateway', { sectionId });
      return res.status(503).json({
        success: false,
        error: {
          code: 'GATEWAY_UNAVAILABLE',
          message:
            'No AI provider is configured for this deployment, so this section cannot be drafted. Nothing was changed.',
        },
      });
    }

    const prompt = `Generate professional ${region} regulatory content for:
Module: ${section.module}
Section: ${section.code} - ${section.title}
Product: ${section.product_code || 'Medical Product'}
Tone: ${tone}
${context ? `Context: ${context}` : ''}
${requirements ? `Requirements: ${requirements}` : ''}
${evidenceBlock}

Return ONLY a JSON object of this exact shape:
{"content": "<the drafted section as clean prose>", "attributions": [{"quote": "<a sentence copied verbatim from content>", "src": <the SRC number>}]}
- "content" is the full section a reviewer reads — do NOT put [SRC-n] markers in it.
- Add one "attributions" entry for each sentence you DERIVED from a provided [SRC-n] source: "quote" copied EXACTLY from "content", "src" the integer n.
- Omit sentences that are your own analysis or not based on a provided source. Never cite a src not shown above.
Provide detailed, compliance-ready content following ${region} guidelines.`;

    draftTurn = openDraftTurn(pool, {
      orgId: tenantId,
      userId: getActorId(req),
      sectionId: String(sectionId),
      request: { tone, region, context: context ?? null, requirements: requirements ?? null,
        ...(assemblySources ? { sources: assemblySources } : {}) },
      prompt,
      audit: { ipAddress: req.ip, userAgent: req.get('user-agent') ?? undefined },
    });
    let gwResponse: Awaited<ReturnType<typeof gw.route>>;
    try {
      gwResponse = await gw.route({
        taskType: 'document_drafting',
        messages: [{ role: 'user', content: prompt }],
        maxTokens: 3000,
        temperature: 0.3,
        // Structured envelope so the model can report which sentences it derived
        // from which source (source-attribution Phase 4). On the default
        // Anthropic provider jsonMode is prompt-instructed; the parse below is
        // tolerant and degrades to plain prose so a malformed response can never
        // break drafting.
        jsonMode: true,
        callerModule: 'authoring-router/generate-draft',
      });
    } catch (aiError) {
      /* A gateway refusal (rate limit, overload, too large, no provider that
         could serve it) answers with its classified code and status; a fault of
         ours is a 500. Neither ever answers with content. */
      if (isGatewayError(aiError)) {
        const { code, message } = classifyGatewayError(aiError);
        logger.warn('ai/draft refused: the AI gateway declined the request', { code, sectionId });
        await fileFailedDraftTurn(draftTurn, `The AI gateway refused this draft (${code}).`);
        return res
          .status(GATEWAY_ERROR_HTTP_STATUS[code])
          .json({ success: false, error: { code, message } });
      }
      await fileFailedDraftTurn(draftTurn, 'The model call failed on the server.');
      return serverError(res, logger, 'drafting AI', aiError);
    }

    // Retain the served response for the failed turn, but never expose or park
    // known cutoff prose, even when its structured envelope looks usable.
    draftTurn?.served(gwResponse);
    assertEditorDraftNotTruncated({ finishReason: gwResponse.finishReason });

    // Parse the structured envelope tolerantly. On ANY shortfall the whole
    // response becomes the draft with no attributions — the draft still lands
    // and is attributed by verified quotes + author lineage (Phase 3).
    // Structured paraphrase is additive; it must never break drafting. The
    // parser is pure and lives in authoring-draft-envelope.ts so the malformed
    // shapes it has to survive are unit-testable without the route.
    const { content: generatedContent, attributions: modelAttributions } =
      parseDraftEnvelope(gwResponse.content);
    if (!generatedContent) {
      /* The provider answered and said nothing usable. That is not a draft and
         it is not an outage; it is refused as an invalid response. */
      logger.warn('ai/draft refused: the provider returned no draft content', {
        sectionId,
        model: gwResponse.model ?? null,
      });
      await fileFailedDraftTurn(draftTurn, 'The AI provider returned no draft content.');
      return res.status(GATEWAY_ERROR_HTTP_STATUS.INVALID_AI_RESPONSE).json({
        success: false,
        error: {
          code: 'INVALID_AI_RESPONSE',
          message:
            'The AI provider returned no draft content, so nothing was drafted. Nothing was changed.',
        },
      });
    }
    if (assemblySources) await readDraftAssemblySources(requestConnectable(req), sourceIdentity, assemblySources);
    /* The engine's check of the draft against what the model was SHOWN, and
       the turn's record, filed before the candidate is parked so the parked
       generator can name it. */
    const drafted = await draftTurn?.drafted(generatedContent, {
      label: `${section.code} ${section.title}`,
      authoringDocId: String(section.doc_id),
      shownEvidence: retrievalStatus === 'ok' ? evidenceShown(evidenceBlock) : null,
      // The header lines exactly as the prompt shows them.
      sectionHeader: `Module: ${section.module}\nSection: ${section.code} - ${section.title}\nProduct: ${section.product_code || 'Medical Product'}`,
      personWords: [context, requirements].filter((v) => typeof v === 'string' && v.trim()).join('\n'),
      retrievalStatus,
    });
    // Park the draft + the sources it came from so the accept endpoint can
    // record verified span-level source lineage (Phase 3). Best-effort:
    // attribution prep must never break drafting, so any failure just omits
    // draftId and the client falls back to a plain save (author lineage).
    let draftId: string | undefined;
    let attributableSources = 0;
    try {
      const rawSourceIds = [
        ...new Set(
          retrievedChunks
            .map((c) => c.sourceId)
            .filter((s): s is string => typeof s === 'string' && s.length > 0),
        ),
      ];
      let evidenceByRaw = new Map<string, number>();
      if (rawSourceIds.length > 0) {
        const { resolveEvidenceSourceIdsByArtifact } = await import(
          '../services/clinical-regulatory-evidence/retrieval-source-link.js'
        );
        // tenantId is the numeric org id (getTenantId → authedOrgId), exactly
        // what the resolver and the lineage writers require.
        evidenceByRaw = await resolveEvidenceSourceIdsByArtifact(tenantId, rawSourceIds);
      }
      const candidateSources = retrievedChunks
        .filter((c) => c.sourceId && evidenceByRaw.has(c.sourceId))
        .map((c) => ({
          evidenceSourceId: evidenceByRaw.get(c.sourceId as string) as number,
          content: c.content,
          title: c.title || null,
        }));
      attributableSources = new Set(candidateSources.map((s) => s.evidenceSourceId)).size;

      // Resolve the model's [SRC-n] paraphrase claims to canonical source
      // ids. SRC-n is the 1-based position in retrievedChunks (the order the
      // evidence block showed the model); keep only a claim whose chunk
      // resolved to a canonical cre_evidence_sources.id — an unresolved or
      // out-of-range src is dropped, never guessed at. The accept gate
      // re-checks each id is one that was retrieved before recording it.
      const assertions = modelAttributions
        .map((a) => {
          const chunk = retrievedChunks[a.src - 1];
          const esid = chunk && chunk.sourceId ? evidenceByRaw.get(chunk.sourceId) : undefined;
          return esid && a.quote.trim() ? { quote: a.quote, sourceId: esid } : null;
        })
        .filter((x): x is { quote: string; sourceId: number } => x !== null);

      const { createDraftCandidate, savedSectionDraftBase } = await import(
        '../services/clinical-regulatory-evidence/draft-candidate-store.js'
      );
      const candidate = await createDraftCandidate(
        tenantId,
        String(sectionId),
        generatedContent,
        candidateSources,
        getActorId(req),
        undefined,
        /* What produced this draft, parked with the source chunks rather
           than round-tripped through the client — "which model wrote
           this" must not be a forgeable claim. The prompt is composed
           inline here, so there is no version to name and a digest of
           the bytes actually sent is the honest identifier. */
        {
          model: gwResponse.model ?? null,
          provider: gwResponse.provider ?? null,
          promptSha256: crypto.createHash('sha256').update(prompt).digest('hex'),
          generatedAt: new Date().toISOString(),
          requestId: gwResponse.requestId ?? null,
          turnRecordId: drafted?.turnRecord.status === 'recorded' ? drafted.turnRecord.id : null,
          finishReason: gwResponse.finishReason ?? null,
          truncated: isTruncated(gwResponse.finishReason),
          ...(vaultSourceReceipt ? { vaultSources: vaultSourceReceipt } : {}),
          ...(assemblySources ? { assemblySources } : {}),
          savedSectionBase: savedSectionDraftBase(section),
        },
        assertions,
      );
      draftId = candidate.id;
    } catch (attrErr: any) {
      console.warn(
        '[Authoring] draft-candidate creation failed (non-fatal):',
        attrErr?.message,
      );
    }

    return res.json({
      success: true,
      /* The only source a draft can have. Declared so a reader of the envelope
         never has to infer from the absence of a `degraded` flag. */
      source: 'model',
      draft: {
        content: generatedContent,
        // Present when the draft was parked for attributed acceptance; POST
        // …/ai/draft/accept with this id records source + author lineage.
        draftId,
        // The engine's check of the draft as generated, and whether its turn was filed.
        check: drafted?.check ?? null,
        turnRecord: drafted?.turnRecord ?? { status: 'not_recorded', reason: 'This draft had no organization to file it under.' },
        metadata: {
          tone,
          region,
          generated_at: new Date().toISOString(),
          model: gwResponse.model,
          provider: gwResponse.provider,
          source: 'model',
          sourcesRetrieved,
          attributableSources,
          /* Carried so a reader can tell an ungrounded draft from a
             grounded one, and a retrieval outage from an empty corpus. */
          retrievalStatus,
          retrievalError,
          retrievalScope: projectScope
            ? { kind: 'project', programId: projectScope.programId, projectId: projectScope.projectId }
            : { kind: 'unavailable', programId: null, projectId: null },
        },
      },
      message:
        sourcesRetrieved > 0
          ? `AI draft generated with ${sourcesRetrieved} Data Room source${
              sourcesRetrieved !== 1 ? 's' : ''
            }`
          : retrievalStatus === 'failed'
            ? 'AI draft generated WITHOUT Data Room evidence — retrieval failed, so this draft is ungrounded and its claims are unverified'
            : 'AI draft generated with no Data Room sources above the relevance threshold',
    });
  } catch (error) {
    if (error instanceof DraftTruncatedError) {
      await fileFailedDraftTurn(draftTurn, 'The AI draft was cut off (DRAFT_TRUNCATED). No candidate was retained.');
      return res.status(422).json({ success: false, error: { code: error.code, message: error.message } });
    }
    const sourceFailure = assemblySourceErrorDetails(error);
    if (sourceFailure) {
      await fileFailedDraftTurn(draftTurn, 'The selected source receipt could not be verified. No candidate was retained.');
      return res.status(sourceFailure.status).json({ success: false, error: { code: sourceFailure.code, message: sourceFailure.message } });
    }
    if (error instanceof AnaProjectScopeError) {
      return res.status(error.status).json({ success: false, error: { code: error.code, message: error.message } });
    }
    console.error('Error generating AI draft:', error);
    await fileFailedDraftTurn(draftTurn, 'Drafting failed on the server.');
    return serverError(res, logger, 'drafting AI', error);
  }
});

// POST /api/authoring/sections/:sectionId/ai/draft/accept - Adopt an AI draft as
// section content AND record span-level source + author lineage, atomically.
//
// This is the persistence point automated source attribution needs: the draft's
// retrieved chunks (parked by POST …/ai/draft) and the accepted text are both in
// hand here, so verified quotes can be recorded against the exact sources the
// draft came from, in the SAME transaction as the content. The save fails closed
// if lineage cannot be recorded — exactly like the manual save gate on
// PATCH /sections/:id. See docs/architecture/SOURCE_ATTRIBUTION_AUTOMATED_DESIGN.md
// Phase 3.
router.post('/sections/:sectionId/ai/draft/accept', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { draftId } = req.body ?? {};
    const tenantId = getTenantId(req);
    const actor = getActorId(req);
    if (!actor) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }
    if (!draftId || typeof draftId !== 'string') {
      return res.status(400).json({ success: false, error: 'draftId is required' });
    }

    // Section must exist and belong to this tenant.
    const sectionResult = await pool.query(
      `SELECT id, doc_id, content FROM authoring_sections WHERE id = $1 AND tenant_id = $2`,
      [sectionId, tenantId],
    );
    if ((sectionResult.rowCount ?? 0) === 0) {
      return res.status(404).json({ success: false, error: 'Section not found' });
    }

    const priorContent: string | null = sectionResult.rows[0].content ?? null;

    const { consumeDraftCandidate, DraftCandidateBaseChangedError } = await import(
      '../services/clinical-regulatory-evidence/draft-candidate-store.js'
    );
    const { enforceSourceAndAuthorLineage } = await import(
      '../services/clinical-regulatory-evidence/lineage-gate.js'
    );

    // Content, its source citations and its author spans commit together or not at
    // all — the same one-connection transaction + gate the manual save uses. The
    // candidate is claimed INSIDE the transaction (single-use), so a rolled-back
    // accept leaves it available for a retry.
    const client = await pool.connect();
    let saved: { rows: any[] } = { rows: [] };
    let acceptedContent = '';
    let attribution = { sourceSpans: 0, authorSpans: 0, distinctSources: 0, coverage: 0 };
    /* Held for the audit entry below. The candidate row is claimed with
       DELETE … RETURNING, so this is the last moment the generator exists
       anywhere — after the transaction it lives only in what we record. */
    let generator: Record<string, unknown> | null = null;
    /* Whether the caller's accepted text still IS the generated draft. */
    let draftModifiedOnAccept = false;
    /* The draft as the model wrote it. When the author edited it before
       accepting, the saved content no longer contains it, and the candidate
       row is consumed below — so it is recorded here or nowhere. */
    let generatedDraft = '';
    /* Whether the accepted content reached the bound filing, and when it did
       not, why — surfaced on the response exactly as the manual save does. */
    let governedCommit: CommitSectionResult | null = null;
    let acceptedAssemblySources: AssemblySourceManifest | undefined;
    let commitAttempted = false;
    let commitConfirmed = false;
    let discardConnection: Error | undefined;
    try {
      await client.query('BEGIN');
      await reserveWritableSection(client, String(sectionId), tenantId);

      const candidate = await consumeDraftCandidate(tenantId, String(sectionId), draftId, client, true);
      if (!candidate) {
        await client.query('ROLLBACK').catch(() => {});
        return res.status(410).json({
          success: false,
          error: {
            code: 'DRAFT_EXPIRED',
            message:
              'This AI draft has expired or was already accepted. Regenerate the draft and try again.',
          },
        });
      }
      generator = candidate.generator as Record<string, unknown> | null;
      assertEditorDraftNotTruncated(candidate.generator);
      const { reserveSectionDraftSources } = await import('../services/authoring/authoring-draft-sources.js');
      await reserveSectionDraftSources(client, tenantId, candidate.generator?.vaultSources, Number(actor));
      if (candidate.generator?.assemblySources !== undefined) {
        acceptedAssemblySources = (await reserveDraftAssemblySources(client,
          { organizationId: tenantId, userId: Number(actor), sectionId: String(sectionId) }, candidate.generator.assemblySources)).manifest;
      }

      // The author may have edited the draft before accepting; attribute what they
      // actually save. Fall back to the draft as generated when no edit is sent.
      // Whether the accepted text still IS the generated draft is recorded on
      // the audit row (draft_modified_on_accept below): "accepted AI draft"
      // must not vouch for words the model never produced.
      acceptedContent =
        typeof req.body?.content === 'string' ? req.body.content : candidate.content;
      draftModifiedOnAccept = acceptedContent !== candidate.content;
      generatedDraft = candidate.content;

      saved = await client.query(
        `UPDATE authoring_sections SET content = $1, updated_at = NOW()
          WHERE id = $2 AND tenant_id = $3 RETURNING *`,
        [acceptedContent, sectionId, tenantId],
      );

      const sources = candidate.sources.map((s) => ({
        sourceId: s.evidenceSourceId,
        content: s.content,
        title: s.title,
      }));
      attribution = await enforceSourceAndAuthorLineage(
        client,
        tenantId,
        { documentTable: 'authoring_sections', documentId: String(sectionId) },
        acceptedContent,
        actor,
        sources,
        // The model's own paraphrase claims, parked at draft time with their
        // source ids already resolved. The gate records each still-present,
        // still-retrieved one as a usage='paraphrased' span — an assertion behind
        // the verified-quote pass, never ahead of it.
        {
          assertions: candidate.assertions,
          // The accepted content IS the machine's draft wherever the author
          // left it unedited: a clause verbatim in what was generated is
          // recorded as AnA's, accepted by this actor; a clause the author
          // changed is the author's own. Attribution by verbatim match against
          // the draft as generated — never by a flag on the whole save.
          acceptedMachineText: [{ authorId: ANA_MACHINE_AUTHOR_ID, text: candidate.content }],
        },
      );

      /* AND THE ACCEPTED DRAFT REACHES THE FILING.
       *
       * This call was missing, exactly as it was on the revert path, and with
       * the same consequence: accepting an AI draft wrote the working copy
       * (`authoring_sections`) and its lineage, and left `c2c_document_sections`
       * — what the filing IS — holding the pre-draft content. So an author
       * accepted a page of regulatory text, saw it in the editor, the audit
       * trail recorded it, and the system of record still showed the old text.
       * AI-assisted drafting is a primary use of this surface, which made this
       * the widest instance of the working-copy/filing drift `commitSectionToFiling`
       * exists to close.
       *
       * In THIS transaction, so the working copy and the filing move together
       * or neither does — the same guarantee the manual save gives. The reason
       * is the author's if they stated one, and otherwise NOT invented: the
       * fact that it came from an AI draft is provenance, recorded on the
       * revision origin and the audit metadata, not a justification for the
       * change. */
      governedCommit = await commitSectionToFiling({
        client,
        sectionId: String(sectionId),
        content: String(acceptedContent ?? ''),
        actorId: String(actor),
        tenantId,
        reason:
          typeof req.body?.changeReason === 'string' && req.body.changeReason.trim()
            ? req.body.changeReason
            : undefined,
        // Unconditional, unlike the manual-save call site above: this whole
        // route exists to accept an AI draft, so the content it commits is by
        // definition AI-drafted — there is no ambiguous zero-contributor case
        // here the way there is on an ordinary interactive save.
        draftSource: 'ana',
      });

      /* The revision and the Part 11 record, IN this transaction (D5,
         2026-09-26). They used to be written after COMMIT, on their own
         connections, with a failure logged as non-fatal — so an accepted AI
         draft could stand in the document with no revision and no record of
         who accepted it. The accept now lands with both or not at all. */
      await createRevision(String(sectionId), acceptedContent, actor, tenantId, client, 'ai-draft-accept');
      await createAuditTrail(
        req,
        saved.rows[0]?.doc_id,
        sectionId,
        'UPDATE',
        candidate.savedPriorContent === undefined ? priorContent : candidate.savedPriorContent,
        acceptedContent,
        /* THE REASON IS THE AUTHOR'S, OR NOT STATED — never "Accepted AI draft".
           Accepting an AI draft is provenance (the revision origin
           'ai-draft-accept' and the metadata below), not a reason WHY this
           regulatory text was chosen. */
        typeof req.body?.changeReason === 'string' && req.body.changeReason.trim()
          ? req.body.changeReason
          : null,
        /* Which model, which provider, which prompt; whether the author edited
           the draft before accepting; and, when they did, the draft as the
           model wrote it, so "accepted AI draft" never vouches for words the
           model did not produce and the words it did produce are not lost. */
        {
          source: 'ai-draft-accept',
          generator,
          ...(acceptedAssemblySources ? { assemblySourceUse: 'verified_generation_input', assemblySources: acceptedAssemblySources } : {}),
          draft_modified_on_accept: draftModifiedOnAccept,
          generated_draft_sha256: textSha256(generatedDraft),
          ...(draftModifiedOnAccept ? { generated_draft: generatedDraft } : {}),
        },
        client,
      );

      commitAttempted = true;
      await client.query('COMMIT');
      commitConfirmed = true;
    } catch (err) {
      if (commitAttempted && !commitConfirmed) {
        discardConnection = new Error('Authoring draft acceptance commit is unconfirmed');
        logger.error('AI draft accept outcome unconfirmed; discarding its connection', { sectionId, tenantId });
        return draftAcceptUnconfirmed(res);
      }
      try { await client.query('ROLLBACK'); }
      catch {
        discardConnection = new Error('Authoring draft acceptance rollback is unconfirmed');
        logger.error('AI draft accept rollback unconfirmed; discarding its connection', { sectionId, tenantId });
        return draftAcceptUnconfirmed(res);
      }
      const sourceFailure = assemblySourceErrorDetails(err);
      if (sourceFailure) return res.status(sourceFailure.status).json({ success: false, error: { code: sourceFailure.code, message: sourceFailure.message } });
      if (err instanceof DraftTruncatedError) {
        return res.status(422).json({ success: false, error: { code: err.code, message: err.message } });
      }
      if (err instanceof DraftCandidateBaseChangedError) {
        return res.status(409).json({ success: false, error: { code: err.code, message: err.message } });
      }
      if ((err as { code?: string }).code === 'DRAFT_SOURCES_UNAVAILABLE') {
        return res.status(409).json({ success: false, error: { code: 'DRAFT_SOURCES_UNAVAILABLE', message: (err as Error).message } });
      }
      if (workflowGovernanceReply(err, res)) return;
      logger.error('AI draft accept refused — content and lineage rolled back together', {
        sectionId,
        tenantId,
        err: err instanceof Error ? err.message : String(err),
      });
      return res.status(500).json({
        success: false,
        error: {
          code: 'LINEAGE_REQUIRED',
          message:
            'The draft was not saved: its source/author lineage or its audit record could not be written. ' +
            'Saving content without provenance or a record is not permitted.',
        },
      });
    } finally {
      client.release(discardConnection);
    }

    res.json({
      success: true,
      section: saved.rows[0],
      attribution,
      message: `AI draft accepted — ${attribution.sourceSpans} verified source citation(s) across ${attribution.distinctSources} source(s); ${attribution.coverage}% of content quoted, the remainder recorded as author-original.`,
      /* Whether the accepted text reached the filing — honest either way, the
         same as the manual save. An unbound accept says it did not, rather than
         letting the two stores drift apart in silence. */
      ...(governedCommit ? { filing: filingResponse(governedCommit) } : {}),
    });
  } catch (error) {
    if (workflowGovernanceReply(error, res)) return;
    console.error('Error accepting AI draft:', error);
    return serverError(res, logger, 'saving accept', error);
  }
});

/* ── What the record says the open section must contain ──────────────────────
   The scan's section-specific expectations came from `ctdRequiredElements`
   below: a table of five CMC codes (3.2.S.1/.2/.3/.4/.7) declared inside the
   handler. For every other code in the CTD — 2.5, 2.7.3, 2.7.4, 4.2.3, 3.2.P,
   1.14.4.1, 5.3.5.x — the author was shown nothing at all about the section's
   required content, while server/services/ind/ctd/authoring-guidance.ts has
   carried `keyContentElements` for all 134 registered codes since the record
   landed.

   The record's elements are DESCRIPTIONS ("Product development rationale
   linking unmet need, MOA, and program design (2.5.1)"), so substring-testing
   content against them would flag essentially every element of every section
   and bury the author in false deficiencies. A substring test cannot verify a
   description, and this does not pretend it can: the elements are served as a
   READ-ONLY statement of what the section must contain, explicitly NOT
   verified by this scan, and they add no check and move no denominator.

   The resolver answers, not a dictionary lookup, because the record carries
   leaves and not parents: '4.2.3' and '3.2.P' have no entry of their own, and
   resolveRequirements / resolveSectionBriefSource handle exact, ancestor and
   parent. A code the record does not index comes back with the resolver's own
   reason and reads as "not indexed" — never as "nothing required". */

/** The record's statement about a section, or its honest absence. */
type RecordRequirements =
  | {
      indexed: true;
      /** Whose entry answered: the section's own, its containing section's, or its children. */
      source: 'exact' | 'ancestor' | 'parent';
      /** The code whose entry answered (the section's own code when `source` is 'exact'). */
      answered_by: string;
      title: string;
      /** What the record says must be present. Empty only for a parent code, which has `contains`. */
      elements: string[];
      /**
       * For a parent code: the registered sections it contains, each with its
       * own requirements, capped at CONTAINS_CAP.
       */
      contains?: Array<{ code: string; title: string }>;
      /** How many contained sections the cap withheld. Zero when all are listed. */
      contains_omitted?: number;
      /** Always false: a description cannot be verified by a keyword test. */
      verified_by_this_check: false;
      note: string;
      /** basisLabel() — recall never reads as the regulator's own text. */
      basis: string;
    }
  | { indexed: false; reason: string };

/* The record carries no typed RegulatoryBasis for a CTD section yet —
   requirements-resolver returns `basis: []` for them and says so in its own
   RequirementAnswer doc — so the basis is stated as exactly what it is:
   compiled recall, rendered through basisLabel, which never lets recall read as
   checked regulator text.

   The record meant here is server/services/ind/ctd/authoring-guidance.ts. That
   path stays in this comment and in the step's -facts.md: `ref` is rendered
   verbatim to a regulatory associate, and a repository path is not something
   the reader of a regulatory statement can act on. */
const CTD_RECORD_BASIS: RegulatoryBasis = {
  ref: 'ICH M4 CTD content, as compiled in the platform record',
  confidence: 'recall',
  note: 'Compiled drafting guidance, not a verbatim regulator citation for this section.',
};

/* The panel is a compact note, so a parent code's listing is capped the way
   the record's own renderer caps the same list — section-brief.ts
   `LIST_CAPS.children` (12) — and the remainder is carried as a count so the
   author is told what was withheld rather than shown a silently short list.
   LIST_CAPS is module-private there; changing that is not this step's file. */
const CONTAINS_CAP = 12;

function recordRequirementsFor(code: unknown): RecordRequirements {
  const requested = String(code ?? '').trim();
  const answer = resolveRequirements({ document: requested });

  if (answer.kind === 'not_indexed') return { indexed: false, reason: answer.reason };
  if (answer.kind !== 'answer' || answer.source.kind !== 'ctd-section') {
    return {
      indexed: false,
      reason:
        `The platform's guidance indexes no CTD section entry for "${requested}". ` +
        'It is not stated here; do not supply requirements from memory as if it were.',
    };
  }

  const src = resolveSectionBriefSource(requested);
  if (!src) {
    return {
      indexed: false,
      reason:
        `The platform's guidance indexes no CTD section entry for "${requested}". ` +
        'It is not stated here; do not supply requirements from memory as if it were.',
    };
  }

  const basis = basisLabel(CTD_RECORD_BASIS);

  if (src.kind === 'parent') {
    const children = src.children ?? [];
    return {
      indexed: true,
      source: 'parent',
      answered_by: src.requested,
      /* The panel prefixes the code, so the title must not repeat it:
         `answer.title` is already "4.2.3 — the sections it contains". */
      title: 'the sections it contains',
      elements: [],
      contains: children.slice(0, CONTAINS_CAP).map((c) => ({ code: c.code, title: c.title })),
      contains_omitted: Math.max(0, children.length - CONTAINS_CAP),
      verified_by_this_check: false,
      note:
        `${src.requested} has no entry of its own in the record; the record carries the requirements of ` +
        'each section it contains. This check does not verify them.',
      basis,
    };
  }

  const entry = src.entry!;
  return {
    indexed: true,
    source: src.kind,
    answered_by: entry.code,
    title: entry.title,
    elements: [...entry.keyContentElements],
    verified_by_this_check: false,
    note: `What the record states section ${entry.code} must contain. This check does not verify these elements.`,
    basis,
  };
}

/**
 * Does the open document agree with itself? One engine run over every section of it
 * (document-figure-consistency.ts): the same figure, in the same frame, stated twice in two
 * sections with two different values — a synopsis against its own body, an overall paragraph
 * against its per-study one. It needs no cited sources, so unlike the save-time check in
 * section-claims-check.ts it reaches a document a person wrote, imported or edited by hand.
 *
 * The role is read from the open section's code. Both sides of a within-document pair carry the
 * same role, so it cancels out of every verdict; reading it from the record keeps it a fact rather
 * than a guess.
 *
 * Null when the read fails — a failed read is never an empty result, which here would read as
 * "the document agrees with itself".
 */
async function documentFigureConsistency(docId: unknown, tenantId: unknown, sectionCode: unknown): Promise<DocumentConsistencyCheck | null> {
  try {
    const rows = await pool.query(
      `SELECT code, title, content FROM authoring_sections
        WHERE doc_id = $1 AND tenant_id = $2
        ORDER BY order_index ASC, code ASC`,
      [docId, tenantId],
    );
    const sections: ConsistencySection[] = rows.rows.map((r: { code: string | null; title: string | null; content: string | null }) => ({
      code: String(r.code ?? ''),
      title: String(r.title ?? ''),
      text: sectionReadableText(r.content),
    }));
    return checkDocumentFigureConsistency(claimDocRoleOf({ ctdSection: String(sectionCode ?? '') }), sections);
  } catch {
    return null;
  }
}

/**
 * The consistency field, present only when the sections were read. An absent field says nothing;
 * an empty one would say "the document agrees with itself", which is the one thing a failed read
 * must never say. A function rather than a ternary in the response literal: the handler is already
 * at the branch-count ceiling, and a reader of the response should see one named thing here.
 */
function consistencyField(check: DocumentConsistencyCheck | null): { document_figure_consistency?: DocumentConsistencyCheck } {
  return check ? { document_figure_consistency: check } : {};
}

// POST /api/authoring/sections/:sectionId/ai/deficiency-scan - Scan for deficiencies
router.post('/sections/:sectionId/ai/deficiency-scan', async (req: Request, res: Response) => {
  try {
    const { sectionId } = req.params;
    const { region = 'FDA', scan_type = 'comprehensive' } = req.body;
    const tenantId = getTenantId(req);

    // Get section content
    const sectionResult = await pool.query(
      `SELECT s.id, s.doc_id, s.code, s.title, s.content, s.order_index, s.track_changes, s.created_at, s.updated_at, s.tenant_id, d.module
       FROM authoring_sections s
       JOIN authoring_documents d ON d.id = s.doc_id
       WHERE s.id = $1 AND s.tenant_id = $2`,
      [sectionId, tenantId]
    );

    if (((sectionResult.rowCount ?? 0) === 0)) {
      return res.status(404).json({
        success: false,
        error: 'Section not found',
      });
    }

    const section = sectionResult.rows[0];
    // One engine run over every section of the open document, before the heuristics below.
    const documentConsistency = await documentFigureConsistency(section.doc_id, tenantId, section.code);

    // Perform deficiency analysis
    const deficiencies: Array<Record<string, unknown>> = [];
    const content = section.content || '';
    const contentLength = content.length;

    /* Which distinct checks ran, and which of them flagged.
       The score was `(10 - deficiencies.length) / 10`, where 10 was a constant
       unrelated to the checks actually performed. The module-keyword check
       alone pushes one deficiency PER missing term — six of them — so a poor
       section reached thirteen deficiencies and scored -30%. A percentage
       below zero is not a signal, it is a bug wearing one. Counting distinct
       checks makes the denominator mean something and keeps the range 0-100,
       and it lets the response say "passed N of M" instead of asking a reader
       to trust a bare number. */
    const checks: Array<{ id: string; flagged: boolean }> = [];
    const checksSkipped: Array<{ id: string; reason: string }> = [];
    const runCheck = (id: string, fn: () => void) => {
      const before = deficiencies.length;
      fn();
      checks.push({ id, flagged: deficiencies.length > before });
    };

    const contentLower = content.toLowerCase();

    runCheck('content_length', () => {
      if (contentLength < 100) {
        deficiencies.push({
          type: 'content_length',
          severity: 'high',
          message:
            'Section content appears insufficient. Regulatory sections typically require detailed information.',
          recommendation: 'Expand content to include all required regulatory elements.',
          location: 'entire_section',
        });
      }
    });

    // Keyword expectations exist only for the five supported CTD module labels.
    // CTIS groups, notifications and other document labels must not inherit CMC
    // expectations or count an unsupported profile as a performed check.
    const requiredKeywords: Record<string, string[]> = {
      M3: ['specification', 'validation', 'stability', 'quality', 'manufacture', 'control'],
      M5: ['efficacy', 'safety', 'adverse', 'clinical', 'endpoint', 'statistical'],
      M2: ['summary', 'overview', 'quality', 'nonclinical', 'clinical'],
      M4: ['toxicology', 'pharmacology', 'ADME', 'carcinogenicity'],
      M1: ['form', 'administrative', 'regulatory'],
    };

    const moduleLabel = String(section.module ?? '');
    const moduleKeywords = Object.prototype.hasOwnProperty.call(requiredKeywords, moduleLabel)
      ? requiredKeywords[moduleLabel] : undefined;
    if (moduleKeywords) {
      runCheck('module_keywords', () => {
        moduleKeywords.forEach(keyword => {
          if (!contentLower.includes(keyword)) {
            deficiencies.push({
              type: 'missing_keyword',
              severity: 'medium',
              /* 2026-10-11: this recommended "Include discussion of <keyword>
                 as required by ${region} guidelines" — a keyword-presence
                 heuristic reported as a requirement of the agency, in the same
                 response this handler frames as "not a compliance
                 determination". The check cannot establish that any agency
                 requires the word, only that the module's keyword profile
                 expects to see the topic discussed, so that is all it now
                 claims. The region is still reported on the response; it is no
                 longer cited as the author of this expectation. */
              message: `Expected term not found in the saved content: "${keyword}"`,
              recommendation:
                `The keyword profile for module ${moduleLabel} expects ${keyword} to be discussed. ` +
                'This is a word-presence signal from that profile, not an agency requirement.',
              location: 'content',
            });
          }
        });
      });
    } else {
      checksSkipped.push({ id: 'module_keywords', reason: `No heuristic keyword profile is defined for document module "${moduleLabel}".` });
    }

    /* CTD required-element check, migrated from POST /ai/validate-compliance.
       That endpoint was a second, callerless implementation of this same
       capability — heuristic keyword presence over section content — and it
       reported `overall_compliance: 'PASS'` whenever its list came back empty.
       Its list was only ever populated for five hardcoded 3.2.S.* codes, so
       for every other section in the CTD it checked nothing and answered PASS.
       The useful half is these per-section element lists; they belong on the
       one scan that has a caller and an honest frame, and the endpoint is
       deleted in the same change (zero duplication). */
    const ctdRequiredElements: Record<string, string[]> = {
      '3.2.S.1': ['nomenclature', 'structure', 'general properties'],
      '3.2.S.2': ['manufacturer', 'manufacturing process', 'controls'],
      '3.2.S.3': ['elucidation of structure', 'impurities'],
      '3.2.S.4': ['specifications', 'analytical procedures', 'validation'],
      '3.2.S.7': ['stability data', 'post-approval stability', 'storage conditions'],
    };
    const ctdElements = ctdRequiredElements[String(section.code)];
    /* Only counted as a check when there IS a list for this section code.
       Running it against a section it has no expectations for and recording a
       pass would inflate the score with a check that never looked at anything
       — the exact arithmetic that let the deleted endpoint answer PASS. */
    if (ctdElements) {
      runCheck('ctd_required_elements', () => {
        ctdElements.forEach(element => {
          if (!contentLower.includes(element)) {
            deficiencies.push({
              type: 'missing_ctd_element',
              severity: 'medium',
              message: `Section ${section.code} would normally discuss ${element}`,
              recommendation: `Add information about ${element} to ${section.code}`,
              location: 'content',
            });
          }
        });
      });
    }

    runCheck('data_presence', () => {
      if (!content.includes('[') && !content.includes('Table') && !content.includes('Figure')) {
        deficiencies.push({
          type: 'missing_data',
          severity: 'medium',
          message: 'No data tables or figures detected',
          recommendation: 'Consider adding supporting data, tables, or figures',
          location: 'content',
        });
      }
    });

    runCheck('placeholder_text', () => {
      const placeholderPatterns = [/\[.*?\]/g, /TBD/gi, /TODO/gi, /XXX/gi];
      placeholderPatterns.forEach(pattern => {
        const matches = content.match(pattern);
        if (matches && matches.length > 0) {
          deficiencies.push({
            type: 'placeholder_text',
            severity: 'high',
            message: `Found placeholder text: ${matches.slice(0, 3).join(', ')}${
              matches.length > 3 ? '...' : ''
            }`,
            recommendation: 'Replace all placeholder text with actual content',
            location: 'multiple',
          });
        }
      });
    });

    runCheck('structure', () => {
      if (!content.includes('\n') || content.split('\n').length < 5) {
        deficiencies.push({
          type: 'poor_structure',
          severity: 'low',
          message: 'Content lacks proper structure and formatting',
          recommendation: 'Add headings, paragraphs, and proper formatting',
          location: 'formatting',
        });
      }
    });

    // Heuristic quality/completeness signal — NOT a 21 CFR compliance
    // determination. It is derived purely from word-count and keyword presence
    // and cannot prove regulatory compliance; labelling a section "compliant" /
    // "non_compliant" on that basis overstates what the check establishes. It is
    // reported as a review signal ('review required' / 'heuristic quality').
    const checksRun = checks.length;
    const checksPassed = checks.filter(c => !c.flagged).length;
    const qualityScore = checksRun > 0 ? Math.round((checksPassed / checksRun) * 100) : 0;

    res.json({
      success: true,
      scan_results: {
        section_id: sectionId,
        section_code: section.code,
        section_title: section.title,
        scan_type,
        region,
        // Heuristic quality/completeness signal. `compliance_score` is retained
        // for backward compatibility with existing readers, but it mirrors the
        // quality signal and is not a compliance determination.
        signal_type: 'heuristic_quality',
        quality_score: qualityScore,
        compliance_score: qualityScore,
        /* The denominator, so a reader is never asked to take the percentage
           on trust — and so the UI can name how many checks actually ran
           rather than hardcoding a number that drifts from the code. */
        checks_run: checksRun,
        checks_passed: checksPassed,
        ...(checksSkipped.length ? { checks_skipped: checksSkipped } : {}),
        /* The record's own statement of what this section must contain, or the
           resolver's reason when it indexes no entry for the code. Always
           present: an omitted field reads as "nothing required", which is the
           one thing this must never say. It is not a check and not counted as
           one — see recordRequirementsFor above. */
        record_requirements: recordRequirementsFor(section.code),
        /* Whether the open DOCUMENT agrees with itself: the same figure stated
           twice in two sections with two different values. Absent when the
           sections could not be read — never an empty result, which would read
           as "it agrees". Not a check and not counted as one. */
        ...consistencyField(documentConsistency),
        status:
          qualityScore >= 80
            ? 'heuristic_ok'
            : qualityScore >= 60
            ? 'review_recommended'
            : 'review_required',
        deficiencies,
        deficiency_count: deficiencies.length,
        scanned_at: new Date().toISOString(),
      },
      message:
        'Heuristic quality scan completed (word-count/keyword signal, not a compliance determination)',
    });
  } catch (error) {
    console.error('Error scanning for deficiencies:', error);
    return serverError(res, logger, 'saving deficiency scan', error);
  }
});

