/* ════ Section order ═════════════════════════════════════════════════════════
 *
 * Every reader of a document — the tree, the export assembler, the PDF and
 * DOCX branches — orders sections by `order_index`, and nothing could ever
 * change it: POST /sections defaulted it and PATCH does not accept it, so a
 * document whose sections were created out of order ASSEMBLED out of order,
 * permanently. Order is part of the filed record, so the write is governed
 * like one: refused on FROZEN/APPROVED (the sealed assembly is what the
 * signatures attest to), the submitted list must be an exact permutation of
 * the document's sections (a partial or foreign list is refused, never
 * partially applied), the renumbering commits in one transaction, and the
 * audit trail records the new order under the actor.
 */
async function assertCurrentSectionPermutation(client: Queryable, docId: string, tenantId: number, ids: string[]): Promise<void> {
  const current = await client.query('SELECT id FROM authoring_sections WHERE doc_id=$1 AND tenant_id=$2', [docId,tenantId]);
  const expected = new Set(current.rows.map((row: { id:string }) => String(row.id)));
  if (new Set(ids).size !== ids.length || ids.length !== expected.size || !ids.every(id => expected.has(id))) {
    throw new WorkflowImportGovernanceError(409,'DOCUMENT_CHANGED_DURING_REORDER','The current sections changed before reordering. Reload the document and retry. Nothing was reordered.');
  }
}

router.post('/docs/:docId/sections/reorder', async (req: Request, res: Response) => {
  try {
    const { docId } = req.params;
    const tenantId = getTenantId(req);
    const actor = getActorEmail(req);
    if (!actor) {
      return res.status(401).json({ success: false, error: 'Authentication required' });
    }
    const ids: unknown = (req.body ?? {}).section_ids;
    if (
      !Array.isArray(ids) ||
      ids.length === 0 ||
      !ids.every((x): x is string => typeof x === 'string' && x.length > 0)
    ) {
      return res.status(400).json({
        success: false,
        error: 'section_ids must be a non-empty array of section ids in the desired order.',
      });
    }

    const parentDoc = await pool.query(
      `SELECT status FROM authoring_documents WHERE id = $1 AND tenant_id = $2`,
      [docId, tenantId]
    );
    if ((parentDoc.rowCount ?? 0) === 0) {
      return res.status(404).json({ success: false, error: 'Document not found' });
    }
    const parentStatus = String(
      (parentDoc.rows[0] as { status?: string | null }).status ?? ''
    ).toUpperCase();
    if (LOCKED_DOCUMENT_STATUSES.has(parentStatus)) {
      return res.status(403).json({
        success: false,
        error: 'Document is FROZEN/APPROVED; its section order is part of the sealed record.',
      });
    }

    const current = await pool.query(
      `SELECT id FROM authoring_sections WHERE doc_id = $1 AND tenant_id = $2`,
      [docId, tenantId]
    );
    const currentIds = new Set<string>(current.rows.map((r: { id: string }) => String(r.id)));
    const submitted = new Set(ids);
    const isPermutation =
      submitted.size === ids.length && // no duplicates
      submitted.size === currentIds.size &&
      ids.every((id) => currentIds.has(id));
    if (!isPermutation) {
      return res.status(409).json({
        success: false,
        error:
          'section_ids must list exactly this document’s sections, each once. ' +
          'The document’s sections changed since you loaded them — reload and retry. Nothing was reordered.',
      });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      await reserveWritableDocument(client, String(docId), tenantId);
      await assertCurrentSectionPermutation(client, String(docId), tenantId, ids);
      for (let i = 0; i < ids.length; i++) {
        await client.query(
          `UPDATE authoring_sections SET order_index = $1, updated_at = NOW()
             WHERE id = $2 AND doc_id = $3 AND tenant_id = $4`,
          [i, ids[i], docId, tenantId]
        );
      }
      await createAuditTrail(req, docId, null, 'REORDER_SECTIONS', null, null, null, { order: ids }, client);
      await client.query('COMMIT');
    } catch (e) {
      await client.query('ROLLBACK').catch(() => {});
      throw e;
    } finally {
      client.release();
    }

    return res.json({ success: true, order: ids });
  } catch (error) {
    if (workflowGovernanceReply(error, res)) return;
    logger.error('section reorder failed', { error });
    return res.status(500).json({
      success: false,
      error: 'Failed to reorder sections. The previous order is unchanged.',
    });
  }
});

/* ════ Section images — the governed figure store ═══════════════════════════
 *
 * Section HTML stores a figure as a REFERENCE (`/api/authoring/images/<id>`),
 * never as base64: the append-only revision ledger and the Part 11 audit rows
 * copy section content on every save, so inlined bytes would multiply every
 * figure by every revision, and the editor's per-keystroke device cache would
 * blow the browser's storage quota on the first chromatogram.
 *
 * Storage REUSES the canonical upload store (`file_uploads` +
 * `uploads/org-{id}/{id}` on disk, via saveDerivedUpload/loadUploadedFile in
 * server/services/ana/uploaded-file-access.ts — the single sanctioned
 * upload-id→bytes resolver, which enforces tenancy on both the org column and
 * the path prefix). A second binary store for the same capability is exactly
 * the parallel path CLAUDE.md rules out.
 *
 * The accepted formats are the ones the DOCX exporter can embed (PNG, JPEG,
 * GIF). WebP is refused at upload rather than dropped at export; SVG is
 * refused because it is a script container, not a picture.
 */

const AUTHORING_IMAGE_MAX_BYTES = 8 * 1024 * 1024;

/* The canonical allowlist (middleware/uploadAllowlist.ts), narrowed to the
   three formats: admitted by extension or by declared type, never by an
   `image/` prefix — SVG and WebP declare one. What gets through is then held to
   its bytes and its name by assertUploadSafe in the handler (IAM-14). */
const imageUpload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: AUTHORING_IMAGE_MAX_BYTES, files: 1 },
  fileFilter: makeUploadFileFilter({
    extensions: ['png', 'jpg', 'jpeg', 'gif'],
    mimeTypes: ['image/png', 'image/jpeg', 'image/gif'],
  }),
});

/** Multer refusals (size, type) arrive as errors; they are client mistakes,
 *  not server faults, and must say so as a 400 with the reason. */
const imageUploadErrors = (err: unknown, _req: Request, res: Response, next: (e?: unknown) => void) => {
  if (!err) return next();
  const message =
    (err as { code?: string })?.code === 'LIMIT_FILE_SIZE'
      ? 'The image is larger than 8 MB. Nothing was uploaded.'
      : err instanceof multer.MulterError
        ? err.message
        : 'Only PNG, JPEG and GIF images are accepted — they are the formats a Word export can embed.';
  return res.status(400).json({ success: false, error: message });
};

/**
 * assertUploadSafe (middleware/uploadSafety.ts) on the bytes in hand: the
 * signature matches the declared type, the name binds the type, and the content
 * scan — fail-CLOSED in production — ran clean. Answers the refusal itself and
 * returns false when the file must not be used.
 */
async function refuseUnsafeUpload(
  res: Response,
  file: { buffer: Buffer; originalname?: string },
  verifyAs: string,
): Promise<boolean> {
  try {
    await assertUploadSafe(file.buffer, verifyAs, file.originalname || 'upload');
    return false;
  } catch (err) {
    if (err instanceof UploadSafetyError) {
      const said = /[.!?]$/.test(err.body.error) ? err.body.error : `${err.body.error}.`;
      res.status(err.status).json({ success: false, error: `${said} Nothing was uploaded.`, code: err.code });
      return true;
    }
    throw err;
  }
}

router.post(
  '/images',
  imageUpload.single('file'),
  imageUploadErrors as never,
  async (req: Request, res: Response) => {
    try {
      const tenantId = getTenantId(req);
      const actorId = getActorId(req);
      if (!actorId) {
        return res.status(401).json({ success: false, error: 'Authentication required' });
      }
      const file = (req as { file?: { buffer?: Buffer; mimetype?: string; originalname?: string } }).file;
      if (!file?.buffer || file.buffer.length === 0) {
        return res.status(400).json({
          success: false,
          error: 'Send the image as multipart/form-data under the field name "file".',
        });
      }

      // The bytes, the name and the scan (IAM-14). This ran the signature
      // check and the scan by hand and read only `scan.clean`, which the
      // scanner reports true when it did not run at all — so a production
      // deployment with no reachable scanner stored every figure unscanned,
      // and `figure.gif` with PNG bytes declared image/png was stored as is.
      if (await refuseUnsafeUpload(res, { buffer: file.buffer, originalname: file.originalname }, file.mimetype ?? '')) {
        return;
      }

      /* Multer's busboy parse breaks the AsyncLocalStorage tenant scope the
         middleware opened (its stream listeners run in the socket's context),
         so under RLS enforcement every query from here on would fail closed.
         Re-enter the exact scope this request was granted — the same repair
         vault-ingest documents. */
      const { runWithTenantScope } = await import('../db/tenantStore');
      const saved = await runWithTenantScope(
        {
          tenantId: String(tenantId),
          orgUuid: (req as { tenantContext?: { organizationUuid?: string | null } }).tenantContext?.organizationUuid ?? null,
          role: (req.user as { role?: string | null })?.role ?? null,
          source: 'request',
          caller: 'server/routes/authoring.router.ts:images',
        },
        async () => {
          const { saveAuthoringImage } = await import('../services/authoring/authoring-image-import');
          return saveAuthoringImage({ pool, tenantId, actor: { id: actorId, email: getActorEmail(req) },
            principal: authoringPrincipalFromRequest(req) }, { documentId: req.body?.documentId,
            file: { buffer: file.buffer!, mimetype: file.mimetype, originalname: file.originalname } });
        }
      );

      return res.status(201).json({
        success: true,
        image: {
          id: saved.fileId,
          url: `/api/authoring/images/${saved.fileId}`,
          mimeType: file.mimetype,
          byteSize: file.buffer.length,
        },
      });
    } catch (error) {
      if (error instanceof AnaProjectScopeError) return res.status(error.status).json({ success:false,code:error.code,error:error.message });
      logger.error('authoring image upload failed', { error });
      return res.status(500).json({ success: false, error: 'Failed to store the image. Nothing was saved.' });
    }
  }
);

router.get('/images/:id', async (req: Request, res: Response) => {
  try {
    const tenantId = getTenantId(req);
    const { loadUploadedFile } = await import('../services/ana/uploaded-file-access.js');
    const { AUTHORING_IMAGE_MIMES } = await import('../export/authoring-images.js');
    // Throws for an unknown id, a foreign tenant's id, or bytes gone from
    // disk — all collapse to the same 404 below, confirming nothing.
    const file = await loadUploadedFile(String(req.params.id), tenantId, { userId: Number(getActorId(req)) });
    if (!AUTHORING_IMAGE_MIMES.has(file.mimeType)) {
      // This endpoint serves figures, not arbitrary tenant uploads.
      return res.status(404).json({ success: false, error: 'Image not found' });
    }
    // Bytes are stable, but project/object grants and source dispositions are
    // current decisions. A year-long fresh cache would bypass their recheck.
    res.setHeader('Content-Type', file.mimeType);
    res.setHeader('Content-Length', String(file.buffer.length));
    res.setHeader('Cache-Control', 'private, no-store');
    res.setHeader('ETag', `"${file.fileId}"`);
    return res.end(file.buffer);
  } catch (error) {
    if (error instanceof AnaProjectScopeError) return res.status(error.status).json({ success: false, code: error.code, error: error.message });
    return res.status(404).json({ success: false, error: 'Image not found' });
  }
});

export default router;

/* ════ Word import ═══════════════════════════════════════════════════════════
 *
 * Four services in this repo already read .docx, and all four call mammoth's
 * `extractRawText` — a flat string, which is correct for the search and
 * retrieval they do and wrong for authoring. A regulatory author importing a
 * technical file needs the TABLES: a predicate comparison, a GSPR matrix, a
 * stability table IS the content, and raw text throws every one away while
 * leaving enough words on screen to look like a successful import
 * (MDX_WORK_ORDER W3-5).
 *
 * This route PARSES ONLY. It writes nothing: it returns the sections it found
 * so the author can see what arrived — how many sections, how many tables, and
 * every warning the conversion produced — and then create them deliberately
 * through POST /sections, which is the governed write with its lineage gate.
 * Importing straight into a document would put un-reviewed content into the
 * governed record on the strength of a drag-and-drop.
 */
const DOCX_MIME = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';

const docxImport = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 25 * 1024 * 1024, files: 1 },
  // A .docx name or the .docx type; the bytes are held to it in the handler.
  fileFilter: makeUploadFileFilter({ extensions: ['docx'], mimeTypes: [DOCX_MIME] }),
});

const docxImportErrors = (err: unknown, _req: Request, res: Response, next: (e?: unknown) => void) => {
  if (!err) return next();
  const message =
    (err as { code?: string })?.code === 'LIMIT_FILE_SIZE'
      ? 'The document is larger than 25 MB. Nothing was imported.'
      : err instanceof multer.MulterError
        ? err.message
        : 'Only .docx files can be imported. A .doc (Word 97-2003) must be saved as .docx first.';
  return res.status(400).json({ success: false, error: message });
};

router.post(
  '/import/docx',
  docxImport.single('file'),
  docxImportErrors,
  async (req: Request, res: Response) => {
    try {
      if (!getActorId(req)) {
        return res.status(401).json({ success: false, error: 'Authentication required' });
      }
      const file = (req as Request & { file?: { buffer?: Buffer; originalname?: string } }).file;
      if (!file?.buffer?.length) {
        return res.status(400).json({ success: false, error: 'No document was uploaded.' });
      }
      /* Verified as the one format this route parses (IAM-14): a Word
         container, scanned, before mammoth opens it. Verifying against the
         .docx type rather than the declared one is deliberate — a browser on a
         machine without Office may declare application/octet-stream for a
         .docx, and the route never stores or serves the file, it only reads
         it as Word. */
      if (await refuseUnsafeUpload(res, { buffer: file.buffer, originalname: file.originalname }, DOCX_MIME)) {
        return;
      }

      const { importDocx } = await import('../import/docx-to-authoring.js');
      const result = await importDocx(file.buffer);

      return res.json({
        success: true,
        sections: result.sections,
        /* Surfaced, never swallowed: an author who is not told a style was
           dropped will file the document believing it arrived intact. */
        warnings: result.warnings,
        counts: result.counts,
      });
    } catch (error) {
      return serverError(res, logger, 'importing the Word document', error);
    }
  },
);

/**
 * Draft-accept store for automated span-level source attribution.
 *
 * The verified-quote attribution primitive (source-attribution.ts) needs the
 * SOURCE'S TEXT to check a quote, and that text is assembled only at RETRIEVAL
 * time — cre_evidence_sources has no full-text column. So when an AI draft is
 * generated (POST /sections/:id/ai/draft), the chunks that backed it (content +
 * the resolved cre_evidence_sources.id for each) are parked here, keyed by a
 * draft id, until the author accepts. The accept endpoint
 * (POST /sections/:id/ai/draft/accept) re-verifies each quote against these exact
 * chunks inside the section-content transaction.
 *
 * ── WHY SERVER-SIDE, NOT ROUND-TRIPPED THROUGH THE CLIENT ────────────────────
 * If the chunks travelled to the browser and back, a client could forge source
 * content to manufacture a quote match — turning "this text appears in this
 * source" from a checkable fact into a client claim, the exact dishonesty the
 * attribution subsystem exists to prevent. The chunks stay on the server; the
 * only client-supplied input at accept time is the (possibly edited) section
 * text, which is precisely what should be attributed.
 *
 * ── SINGLE-USE + TENANT-SCOPED ───────────────────────────────────────────────
 * consumeDraftCandidate claims a candidate with DELETE … RETURNING, scoped to
 * (org, section, id) and unexpired, so it can be accepted exactly once and never
 * across tenants. Run on the caller's transaction client, the claim commits with
 * the content write and rolls back with it (a refused accept leaves the candidate
 * for a retry). The table also carries RLS (see the migration) as defence in
 * depth behind these explicit predicates.
 *
 * @module server/services/clinical-regulatory-evidence/draft-candidate-store
 */

import { pool } from '../../db';
import { createHash } from 'node:crypto';
import type { Queryable } from './span-lineage.service';
import type { ParaphraseAssertion } from './source-attribution';

/** Default executor — the pool (its own transaction per statement). */
const defaultExec: Queryable = pool as unknown as Queryable;

/** One retrieved chunk that resolved to a canonical Data Room source. */
export interface DraftCandidateSource {
  /** cre_evidence_sources.id the chunk came from. */
  evidenceSourceId: number;
  /** The chunk's content — the haystack a generated quote is checked against. */
  content: string;
  title: string | null;
}

/**
 * What produced a draft. Parked server-side with the source chunks for the same
 * reason they are: round-tripped through the client, "which model wrote this"
 * stops being a fact and becomes a claim the client could forge.
 */
export interface DraftGenerator {
  model: string | null;
  provider: string | null;
  /** SHA-256 of the prompt actually sent. The authoring route composes its
   *  prompt inline, so there is no version to name — a digest is a real
   *  identifier where a made-up version number would only look like one. */
  promptSha256: string | null;
  /** Set where a route genuinely has a versioned prompt file. */
  promptVersion?: string | null;
  generatedAt: string;
  /** The gateway request that produced the draft: its ledger row (round 12, RT-6). */
  requestId?: string | null;
  /** The AnA turn record the draft was filed under (services/ana/turn-record-draft.ts). */
  turnRecordId?: string | null;
  /** Actual gateway status, retained server-side; absence is legacy/unconfirmed. */
  finishReason?: string | null;
  /** Derived from the reported reason; false is not proof of complete content. */
  truncated?: boolean;
  /** Exact project Vault versions shown to this draft; revalidated on accept. */
  vaultSources?: import('../authoring/authoring-draft-sources.js').SectionDraftSourceReceipt;
  /** Exact selected catalogue excerpts verified before and after generation. */
  assemblySources?: import('../../../shared/authoring/assembly-sources').AssemblySourceManifest;
  /** The saved section the server actually drafted against. Never accepted
   * from the client. Kept in the existing generator JSON, without new storage. */
  savedSectionBase?: SavedSectionDraftBase;
}

export interface SavedSectionDraftBase {
  version: 1;
  sectionId: string;
  docId: string;
  code: string | null;
  title: string | null;
  contentSha256: string;
  updatedAt: string | null;
}

/** Both generation and the locked accept use the same saved-base vocabulary. */
export function savedSectionDraftBase(section: Record<string, unknown>): SavedSectionDraftBase {
  const updated = section.base_updated_at ?? section.updated_at;
  return {
    version: 1,
    sectionId: String(section.id),
    docId: String(section.doc_id),
    code: typeof section.code === 'string' ? section.code : null,
    title: typeof section.title === 'string' ? section.title : null,
    contentSha256: createHash('sha256').update(JSON.stringify(section.content ?? null)).digest('hex'),
    updatedAt: updated instanceof Date ? updated.toISOString() : typeof updated === 'string' ? updated : null,
  };
}

export class DraftCandidateBaseChangedError extends Error {
  readonly code = 'SECTION_BASE_CHANGED';
  constructor() {
    super('The candidate\'s saved section base could not be verified against the current section. Nothing was saved and the candidate was retained. Inspect the current section and generate a fresh draft before accepting.');
    this.name = 'DraftCandidateBaseChangedError';
  }
}

function sameSavedBase(raw: unknown, current: SavedSectionDraftBase): boolean {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return false;
  const stored = raw as Record<string, unknown>;
  return Object.entries(current).every(([key, value]) => stored[key] === value);
}

async function lockSavedDraftBase(exec: Queryable, orgId: number, sectionId: string, draftId: string) {
  // The caller reserves the parent first. Refuse before DELETE while both the
  // candidate and child are locked, so a changed base cannot consume a draft.
  const locked = await exec.query<Record<string, unknown>>(
    `SELECT c.generator, s.id, s.doc_id, s.code, s.title, s.content,
            s.updated_at::text AS base_updated_at
       FROM authoring_ai_draft_candidates c
       JOIN authoring_sections s ON s.id=c.section_id AND s.tenant_id=c.organization_id
      WHERE c.id=$1 AND c.organization_id=$2 AND c.section_id=$3 AND c.expires_at>=NOW()
      FOR UPDATE OF c, s`,
    [draftId, orgId, sectionId],
  );
  const section = locked.rows[0];
  if (!section) return null;
  const generator = typeof section.generator === 'string' ? safeParseObject(section.generator) : section.generator;
  const storedBase = generator && typeof generator === 'object' && 'savedSectionBase' in generator
    ? generator.savedSectionBase : null;
  if (!sameSavedBase(storedBase, savedSectionDraftBase(section))) {
    throw new DraftCandidateBaseChangedError();
  }
  return { savedPriorContent: typeof section.content === 'string' ? section.content : null };
}

export interface DraftCandidate {
  id: string;
  sectionId: string;
  content: string;
  sources: DraftCandidateSource[];
  createdBy: string | null;
  /** null when the draft predates generator capture, or the route did not
   *  supply one — never a guess at the current default model. */
  generator: DraftGenerator | null;
  /** The model's self-reported paraphrase claims ([{ quote, sourceId }]). Fed to
   *  the accept gate, which records each still-present, still-resolvable claim as
   *  a usage='paraphrased' span. Empty when the draft carried none (source-
   *  attribution Phase 4). */
  assertions: ParaphraseAssertion[];
  /** Read under the accept's section lock, for the truthful before-content
   * audit entry. Present only when the route requested saved-base validation. */
  savedPriorContent?: string | null;
}

/**
 * Park an AI draft and the sources that back it.
 *
 * Opportunistically deletes this org's expired candidates first, so the table
 * self-cleans without a separate job. That cleanup is best-effort: a failure must
 * never block drafting. `expires_at` is computed in SQL (NOW() + TTL) to avoid
 * app/DB clock skew.
 */
export async function createDraftCandidate(
  orgId: number,
  sectionId: string,
  content: string,
  sources: DraftCandidateSource[],
  createdBy: string | null,
  exec: Queryable = defaultExec,
  generator: DraftGenerator | null = null,
  assertions: ParaphraseAssertion[] = [],
): Promise<{ id: string; expiresAt: string }> {
  try {
    await exec.query(
      `DELETE FROM authoring_ai_draft_candidates
        WHERE organization_id = $1 AND expires_at < NOW()`,
      [orgId],
    );
  } catch {
    /* non-fatal: stale rows are harmless and filtered on read anyway */
  }

  const { rows } = await exec.query<{ id: string; expires_at: string }>(
    `INSERT INTO authoring_ai_draft_candidates
       (section_id, organization_id, content, sources, created_by, generator, assertions, expires_at)
     VALUES ($1, $2, $3, $4::jsonb, $5, $6::jsonb, $7::jsonb, NOW() + INTERVAL '2 hours')
     RETURNING id, expires_at`,
    [
      sectionId,
      orgId,
      content,
      JSON.stringify(sources ?? []),
      createdBy,
      generator ? JSON.stringify(generator) : null,
      JSON.stringify(Array.isArray(assertions) ? assertions : []),
    ],
  );
  return { id: rows[0].id, expiresAt: String(rows[0].expires_at) };
}

/** A generator field as stored: a string, or null for anything else. */
const stringOrNull = (v: unknown): string | null => (typeof v === 'string' ? v : null);

/**
 * Claim a parked candidate for acceptance — single-use, tenant- and section-
 * scoped, unexpired. Returns null when no such live candidate exists (wrong
 * tenant/section, already accepted, or past its TTL). MUST be passed the accept
 * transaction's client so the claim commits with the content write.
 */
export async function consumeDraftCandidate(
  orgId: number,
  sectionId: string,
  draftId: string,
  exec: Queryable = defaultExec,
  validateSavedBase = false,
): Promise<DraftCandidate | null> {
  let savedBase: { savedPriorContent: string | null } | null | undefined;
  if (validateSavedBase) {
    savedBase = await lockSavedDraftBase(exec, orgId, sectionId, draftId);
    if (!savedBase) return null;
  }
  const { rows } = await exec.query<{
    id: string;
    section_id: string;
    content: string;
    sources: unknown;
    created_by: string | null;
    generator: unknown;
    assertions: unknown;
  }>(
    `DELETE FROM authoring_ai_draft_candidates
      WHERE id = $1 AND organization_id = $2 AND section_id = $3 AND expires_at >= NOW()
      RETURNING id, section_id, content, sources, created_by, generator, assertions`,
    [draftId, orgId, sectionId],
  );
  if (rows.length === 0) return null;

  const r = rows[0];
  // jsonb comes back parsed from node-postgres and (usually) from PGlite; tolerate
  // a string just in case, and drop any entry without a usable integer source id.
  const raw = Array.isArray(r.sources)
    ? r.sources
    : typeof r.sources === 'string'
      ? safeParseArray(r.sources)
      : [];
  const sources: DraftCandidateSource[] = raw
    .filter((s: any) => s && Number.isInteger(Number(s.evidenceSourceId)) && Number(s.evidenceSourceId) > 0)
    .map((s: any) => ({
      evidenceSourceId: Number(s.evidenceSourceId),
      content: typeof s.content === 'string' ? s.content : '',
      title: s.title ?? null,
    }));

  /* Same tolerance as `sources` above: jsonb usually arrives parsed, but a
     string is possible. An unparseable value becomes null rather than a
     partially-populated generator — half a provenance record invites a reader
     to trust the half that is there. */
  const generator = parsedDraftGenerator(r.generator);

  // Same tolerance as `sources`: usually parsed jsonb, possibly a string. Keep
  // only well-formed claims — a non-empty quote string and a positive integer
  // source id — so a malformed entry cannot smuggle an unresolved id into the
  // accept gate (which itself re-checks the source is one that was retrieved).
  const rawAssertions = Array.isArray(r.assertions)
    ? r.assertions
    : typeof r.assertions === 'string'
      ? safeParseArray(r.assertions)
      : [];
  const assertions: ParaphraseAssertion[] = rawAssertions
    .filter(
      (a: any) =>
        a &&
        typeof a.quote === 'string' &&
        a.quote.length > 0 &&
        Number.isInteger(Number(a.sourceId)) &&
        Number(a.sourceId) > 0,
    )
    .map((a: any) => ({ quote: a.quote as string, sourceId: Number(a.sourceId) }));

  return {
    id: r.id,
    sectionId: r.section_id,
    content: r.content,
    sources,
    createdBy: r.created_by,
    generator,
    assertions,
    ...savedBase,
  };
}

function parsedDraftGenerator(raw: unknown): DraftGenerator | null {
  const g = typeof raw === 'string' ? safeParseObject(raw) : raw;
  if (!g || typeof g !== 'object' || Array.isArray(g)) return null;
  const value = g as Record<string, unknown>;
  return {
    model: stringOrNull(value.model),
    provider: stringOrNull(value.provider),
    promptSha256: stringOrNull(value.promptSha256),
    promptVersion: stringOrNull(value.promptVersion),
    generatedAt: stringOrNull(value.generatedAt) ?? '',
    requestId: stringOrNull(value.requestId),
    turnRecordId: stringOrNull(value.turnRecordId),
    ...(value.finishReason !== undefined ? { finishReason: stringOrNull(value.finishReason) } : {}),
    ...(value.truncated !== undefined ? { truncated: value.truncated === true } : {}),
    // Preserve malformed recorded receipts for the fail-closed accept verifier.
    ...(value.vaultSources !== undefined
      ? { vaultSources: value.vaultSources as DraftGenerator['vaultSources'] } : {}),
    ...(value.assemblySources !== undefined
      ? { assemblySources: value.assemblySources as DraftGenerator['assemblySources'] } : {}),
    ...(value.savedSectionBase && typeof value.savedSectionBase === 'object'
      ? { savedSectionBase: value.savedSectionBase as SavedSectionDraftBase } : {}),
  };
}

function safeParseObject(s: string): Record<string, unknown> | null {
  try {
    const v = JSON.parse(s);
    return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
  } catch {
    return null;
  }
}

function safeParseArray(s: string): any[] {
  try {
    const v = JSON.parse(s);
    return Array.isArray(v) ? v : [];
  } catch {
    return [];
  }
}
